}

contracts/EmergencyPause.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

/**
 * @title EmergencyPause
 * @dev 紧急暂停合约 - 紧急暂停机制、多签控制
 * 
 * Features:
 * - 紧急暂停机制
 * - 多签控制
 * - 暂停所有合约操作
 * - 合约注册管理
 */
contract EmergencyPause is Ownable {
    // 全局暂停状态
    bool public globalPauseActive = false;
    
    // 多签控制
    address public multiSigWallet;
    bool public multiSigEnabled = false;
    uint256 public requiredSignatures = 2; // 需要的签名数量（简化版，实际应使用 Gnosis Safe 等）
    
    // 紧急暂停操作员
    address public emergencyPauseOperator;
    
    // 注册的合约列表
    address[] public registeredContracts;
    mapping(address => bool) public isRegistered;
    mapping(address => bool) public pausedContracts; // 暂停的合约
    
    // 暂停记录
    struct PauseRecord {
        address contractAddress;
        address pausedBy;
        uint256 timestamp;
        string reason;
        bool isActive;
    }
    
    mapping(address => PauseRecord[]) public pauseHistory; // 合约暂停历史
    
    // 事件
    event GlobalPauseActivated(address indexed pausedBy, string reason, uint256 timestamp);
    event GlobalPauseDeactivated(address indexed unpausedBy, uint256 timestamp);
    event ContractPaused(address indexed contractAddress, address indexed pausedBy, string reason, uint256 timestamp);
    event ContractUnpaused(address indexed contractAddress, address indexed unpausedBy, uint256 timestamp);
    event ContractRegistered(address indexed contractAddress, address indexed registeredBy, uint256 timestamp);
    event ContractUnregistered(address indexed contractAddress, address indexed unregisteredBy, uint256 timestamp);
    event EmergencyPauseOperatorUpdated(address indexed oldOperator, address indexed newOperator);
    event MultiSigWalletUpdated(address indexed oldWallet, address indexed newWallet, bool enabled);
    
    /**
     * @dev Constructor
     */
    constructor() Ownable(msg.sender) {
        emergencyPauseOperator = msg.sender;
    }
    
    /**
     * @dev Modifier: Only Owner or Emergency Pause Operator
     */
    modifier onlyOwnerOrOperator() {
        require(
            msg.sender == owner() || msg.sender == emergencyPauseOperator,
            "EmergencyPause: Not authorized"
        );
        _;
    }
    
    /**
     * @dev Modifier: Only Owner or MultiSig
     */
    modifier onlyOwnerOrMultiSig() {
        if (multiSigEnabled) {
            require(msg.sender == multiSigWallet, "EmergencyPause: Only multi-sig wallet can call");
        } else {
            require(msg.sender == owner(), "EmergencyPause: Only owner can call");
        }
        _;
    }
    
    /**
     * @dev 设置紧急暂停操作员
     * @param operator 操作员地址
     */
    function setEmergencyPauseOperator(address operator) external onlyOwner {
        require(operator != address(0), "EmergencyPause: Invalid operator address");
        address oldOperator = emergencyPauseOperator;
        emergencyPauseOperator = operator;
        emit EmergencyPauseOperatorUpdated(oldOperator, operator);
    }
    
    /**
     * @dev 设置多签钱包
     * @param _multiSigWallet 多签钱包地址
     * @param _enabled 是否启用多签
     */
    function setMultiSigWallet(address _multiSigWallet, bool _enabled) external onlyOwner {
        address oldWallet = multiSigWallet;
        multiSigWallet = _multiSigWallet;
        multiSigEnabled = _enabled;
        emit MultiSigWalletUpdated(oldWallet, _multiSigWallet, _enabled);
    }
    
    /**
     * @dev 注册合约
     * @param contractAddress 合约地址
     */
    function registerContract(address contractAddress) external onlyOwner {
        require(contractAddress != address(0), "EmergencyPause: Invalid contract address");
        require(!isRegistered[contractAddress], "EmergencyPause: Contract already registered");
        
        registeredContracts.push(contractAddress);
        isRegistered[contractAddress] = true;
        
        emit ContractRegistered(contractAddress, msg.sender, block.timestamp);
    }
    
    /**
     * @dev 取消注册合约
     * @param contractAddress 合约地址
     */
    function unregisterContract(address contractAddress) external onlyOwner {
        require(isRegistered[contractAddress], "EmergencyPause: Contract not registered");
        
        isRegistered[contractAddress] = false;
        
        // 从数组中移除（简化处理，不实际删除）
        // 实际应用中可以使用更高效的数据结构
        
        emit ContractUnregistered(contractAddress, msg.sender, block.timestamp);
    }
    
    /**
     * @dev 全局暂停（暂停所有注册的合约）
     * @param reason 暂停原因
     */
    function globalPause(string memory reason) external onlyOwnerOrMultiSig {
        require(!globalPauseActive, "EmergencyPause: Already globally paused");
        
        globalPauseActive = true;
        
        // 暂停所有注册的合约
        for (uint256 i = 0; i < registeredContracts.length; i++) {
            address contractAddress = registeredContracts[i];
            if (isRegistered[contractAddress] && !pausedContracts[contractAddress]) {
                _pauseContract(contractAddress, reason);
            }
        }
        
        emit GlobalPauseActivated(msg.sender, reason, block.timestamp);
    }
    
    /**
     * @dev 解除全局暂停
     */
    function globalUnpause() external onlyOwnerOrMultiSig {
        require(globalPauseActive, "EmergencyPause: Not globally paused");
        
        globalPauseActive = false;
        
        // 解除所有注册合约的暂停
        for (uint256 i = 0; i < registeredContracts.length; i++) {
            address contractAddress = registeredContracts[i];
            if (isRegistered[contractAddress] && pausedContracts[contractAddress]) {
                _unpauseContract(contractAddress);
            }
        }
        
        emit GlobalPauseDeactivated(msg.sender, block.timestamp);
    }
    
    /**
     * @dev 暂停单个合约（操作员或Owner）
     * @param contractAddress 合约地址
     * @param reason 暂停原因
     */
    function pauseContract(address contractAddress, string memory reason) external onlyOwnerOrOperator {
        require(contractAddress != address(0), "EmergencyPause: Invalid contract address");
        require(isRegistered[contractAddress], "EmergencyPause: Contract not registered");
        require(!pausedContracts[contractAddress], "EmergencyPause: Contract already paused");
        
        _pauseContract(contractAddress, reason);
    }
    
    /**
     * @dev 解除单个合约暂停（仅Owner或多签）
     * @param contractAddress 合约地址
     */
    function unpauseContract(address contractAddress) external onlyOwnerOrMultiSig {
        require(contractAddress != address(0), "EmergencyPause: Invalid contract address");
        require(pausedContracts[contractAddress], "EmergencyPause: Contract not paused");
        
        _unpauseContract(contractAddress);
    }
    
    /**
     * @dev 内部函数：暂停合约
     * @param contractAddress 合约地址
     * @param reason 暂停原因
     */
    function _pauseContract(address contractAddress, string memory reason) internal {
        pausedContracts[contractAddress] = true;
        
        // 记录暂停历史
        pauseHistory[contractAddress].push(PauseRecord({
            contractAddress: contractAddress,
            pausedBy: msg.sender,
            timestamp: block.timestamp,
            reason: reason,
            isActive: true
        }));
        
        // 尝试调用合约的 pause() 函数（如果合约支持 Pausable）
        (bool success, ) = contractAddress.call(
            abi.encodeWithSignature("pause()")
        );
        // 即使调用失败也不回滚，因为可能合约不支持 pause()
        // 我们仍然记录暂停状态
        success; // 避免未使用变量警告
        
        emit ContractPaused(contractAddress, msg.sender, reason, block.timestamp);
    }
    
    /**
     * @dev 内部函数：解除合约暂停
     * @param contractAddress 合约地址
     */
    function _unpauseContract(address contractAddress) internal {
        pausedContracts[contractAddress] = false;
        
        // 更新暂停历史
        PauseRecord[] storage history = pauseHistory[contractAddress];
        for (uint256 i = history.length; i > 0; i--) {
            if (history[i - 1].isActive) {
                history[i - 1].isActive = false;
                break;
            }
        }
        
        // 尝试调用合约的 unpause() 函数（如果合约支持 Pausable）
        (bool success, ) = contractAddress.call(
            abi.encodeWithSignature("unpause()")
        );
        // 即使调用失败也不回滚，因为可能合约不支持 unpause()
        // 我们仍然记录解除暂停状态
        success; // 避免未使用变量警告
        
        emit ContractUnpaused(contractAddress, msg.sender, block.timestamp);
    }
    
    /**
     * @dev 检查合约是否暂停
     * @param contractAddress 合约地址
     * @return paused 是否暂停
     */
    function isPaused(address contractAddress) external view returns (bool paused) {
        // 如果全局暂停激活，所有合约都视为暂停
        if (globalPauseActive) {
            return true;
        }
        
        // 检查单个合约的暂停状态
        return pausedContracts[contractAddress];
    }
    
    /**
     * @dev 获取注册的合约列表
     * @return contracts 合约地址数组
     */
    function getRegisteredContracts() external view returns (address[] memory contracts) {
        return registeredContracts;
    }
    
    /**
     * @dev 获取合约的暂停历史
     * @param contractAddress 合约地址
     * @return history 暂停历史记录
     */
    function getPauseHistory(address contractAddress) external view returns (PauseRecord[] memory history) {
        return pauseHistory[contractAddress];
    }
    
    /**
     * @dev 获取紧急暂停状态
     * @return globalPause_ 全局暂停状态
     * @return registeredCount 注册的合约数量
     * @return pausedCount 暂停的合约数量
     */
    function getEmergencyPauseStatus() external view returns (
        bool globalPause_,
        uint256 registeredCount,
        uint256 pausedCount
    ) {
        globalPause_ = globalPauseActive;
        registeredCount = registeredContracts.length;
        
        // 计算暂停的合约数量
        pausedCount = 0;
        for (uint256 i = 0; i < registeredContracts.length; i++) {
            if (pausedContracts[registeredContracts[i]]) {
                pausedCount++;
            }
        }
        
        return (globalPause_, registeredCount, pausedCount);
    }
}

contracts/LiquidityManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title LiquidityManager
 * @dev 流动性池管理合约 - 流动性池控制、自动补充
 * 
 * Features:
 * - 流动性池控制（维持 20-30% 流动性）
 * - 自动补充流动性
 * - 流动性比例监控
 * - 与 SwapContract 集成
 */
contract LiquidityManager is Ownable, Pausable, ReentrancyGuard {
    using SafeERC20 for IERC20;
    
    // Token addresses
    IERC20 public immutable rwaToken;
    IERC20 public immutable usdtToken;
    
    // Contract addresses
    address public swapContractAddress;  // SwapContract 地址
    address public treasuryAddress;       // TreasuryContract 地址
    
    // 流动性配置
    uint256 public minLiquidityRatio = 20;   // 最小流动性比例 20%
    uint256 public targetLiquidityRatio = 30; // 目标流动性比例 30%
    uint256 public maxLiquidityRatio = 50;    // 最大流动性比例 50%
    
    // 自动补充配置
    bool public autoReplenishEnabled = true;  // 是否启用自动补充
    uint256 public replenishThreshold = 15;   // 补充阈值（低于此值触发补充）
    
    // 流动性记录
    uint256 public totalLiquidityAdded;      // 总添加的流动性
    uint256 public lastReplenishTime;        // 上次补充时间
    uint256 public replenishCooldown = 1 days; // 补充冷却期（1天）
    
    // 事件
    event LiquidityAdded(uint256 rwaAmount, uint256 usdtAmount, uint256 timestamp);
    event LiquidityRemoved(uint256 rwaAmount, uint256 usdtAmount, uint256 timestamp);
    event AutoReplenishTriggered(uint256 currentRatio, uint256 targetRatio, uint256 rwaAmount, uint256 usdtAmount, uint256 timestamp);
    event MinLiquidityRatioUpdated(uint256 oldRatio, uint256 newRatio);
    event TargetLiquidityRatioUpdated(uint256 oldRatio, uint256 newRatio);
    event MaxLiquidityRatioUpdated(uint256 oldRatio, uint256 newRatio);
    event AutoReplenishEnabledUpdated(bool enabled);
    event ReplenishThresholdUpdated(uint256 oldThreshold, uint256 newThreshold);
    event SwapContractAddressUpdated(address indexed oldAddress, address indexed newAddress);
    event TreasuryAddressUpdated(address indexed oldAddress, address indexed newAddress);
    
    /**
     * @dev Constructor
     * @param _rwaToken RWA token address
     * @param _usdtToken USDT token address
     */
    constructor(address _rwaToken, address _usdtToken) Ownable(msg.sender) {
        require(_rwaToken != address(0), "LiquidityManager: Invalid RWA token address");
        require(_usdtToken != address(0), "LiquidityManager: Invalid USDT token address");
        
        rwaToken = IERC20(_rwaToken);
        usdtToken = IERC20(_usdtToken);
    }
    
    /**
     * @dev 设置 SwapContract 地址
     * @param _swapContractAddress SwapContract 地址
     */
    function setSwapContractAddress(address _swapContractAddress) external onlyOwner {
        require(_swapContractAddress != address(0), "LiquidityManager: Invalid address");
        address oldAddress = swapContractAddress;
        swapContractAddress = _swapContractAddress;
        emit SwapContractAddressUpdated(oldAddress, _swapContractAddress);
    }
    
    /**
     * @dev 设置 TreasuryContract 地址
     * @param _treasuryAddress TreasuryContract 地址
     */
    function setTreasuryAddress(address _treasuryAddress) external onlyOwner {
        require(_treasuryAddress != address(0), "LiquidityManager: Invalid address");
        address oldAddress = treasuryAddress;
        treasuryAddress = _treasuryAddress;
        emit TreasuryAddressUpdated(oldAddress, _treasuryAddress);
    }
    
    /**
     * @dev 设置最小流动性比例
     * @param newRatio 新的比例（百分比，20 = 20%）
     */
    function setMinLiquidityRatio(uint256 newRatio) external onlyOwner {
        require(newRatio > 0 && newRatio <= 100, "LiquidityManager: Invalid ratio");
        require(newRatio < targetLiquidityRatio, "LiquidityManager: Min ratio must be less than target ratio");
        uint256 oldRatio = minLiquidityRatio;
        minLiquidityRatio = newRatio;
        emit MinLiquidityRatioUpdated(oldRatio, newRatio);
    }
    
    /**
     * @dev 设置目标流动性比例
     * @param newRatio 新的比例（百分比，30 = 30%）
     */
    function setTargetLiquidityRatio(uint256 newRatio) external onlyOwner {
        require(newRatio > 0 && newRatio <= 100, "LiquidityManager: Invalid ratio");
        require(newRatio > minLiquidityRatio && newRatio <= maxLiquidityRatio, "LiquidityManager: Invalid ratio range");
        uint256 oldRatio = targetLiquidityRatio;
        targetLiquidityRatio = newRatio;
        emit TargetLiquidityRatioUpdated(oldRatio, newRatio);
    }
    
    /**
     * @dev 设置最大流动性比例
     * @param newRatio 新的比例（百分比，50 = 50%）
     */
    function setMaxLiquidityRatio(uint256 newRatio) external onlyOwner {
        require(newRatio > 0 && newRatio <= 100, "LiquidityManager: Invalid ratio");
        require(newRatio > targetLiquidityRatio, "LiquidityManager: Max ratio must be greater than target ratio");
        uint256 oldRatio = maxLiquidityRatio;
        maxLiquidityRatio = newRatio;
        emit MaxLiquidityRatioUpdated(oldRatio, newRatio);
    }
    
    /**
     * @dev 设置自动补充开关
     * @param enabled 是否启用
     */
    function setAutoReplenishEnabled(bool enabled) external onlyOwner {
        autoReplenishEnabled = enabled;
        emit AutoReplenishEnabledUpdated(enabled);
    }
    
    /**
     * @dev 设置补充阈值
     * @param newThreshold 新的阈值（百分比）
     */
    function setReplenishThreshold(uint256 newThreshold) external onlyOwner {
        require(newThreshold > 0 && newThreshold < minLiquidityRatio, "LiquidityManager: Invalid threshold");
        uint256 oldThreshold = replenishThreshold;
        replenishThreshold = newThreshold;
        emit ReplenishThresholdUpdated(oldThreshold, newThreshold);
    }
    
    /**
     * @dev 获取当前流动性比例
     * @return ratio 当前流动性比例（百分比）
     * @return rwaLiquidity RWA 流动性
     * @return usdtLiquidity USDT 流动性
     */
    function getCurrentLiquidityRatio() public view returns (
        uint256 ratio,
        uint256 rwaLiquidity,
        uint256 usdtLiquidity
    ) {
        if (swapContractAddress == address(0)) {
            return (0, 0, 0);
        }
        
        // 从 SwapContract 获取池子余额
        (bool success, bytes memory data) = swapContractAddress.staticcall(
            abi.encodeWithSignature("getPoolStatus()")
        );
        
        if (!success || data.length == 0) {
            return (0, 0, 0);
        }
        
        (uint256 rwaBalance, uint256 stRwaBalance, , ) = abi.decode(data, (uint256, uint256, uint256, uint256));
        
        // 计算流动性（使用 RWA 池子余额作为流动性指标）
        rwaLiquidity = rwaBalance;
        usdtLiquidity = stRwaBalance; // stRWA 代表 USDT 等值
        
        // 计算总供应量
        uint256 totalSupply = rwaToken.totalSupply();
        if (totalSupply == 0) {
            return (0, rwaLiquidity, usdtLiquidity);
        }
        
        // 计算流动性比例（基于 RWA 供应量）
        ratio = (rwaLiquidity * 100) / totalSupply;
        
        return (ratio, rwaLiquidity, usdtLiquidity);
    }
    
    /**
     * @dev 检查是否需要补充流动性
     * @return needReplenish 是否需要补充
     * @return currentRatio 当前比例
     * @return targetAmount 目标流动性金额
     */
    function checkReplenishNeeded() public view returns (
        bool needReplenish,
        uint256 currentRatio,
        uint256 targetAmount
    ) {
        if (!autoReplenishEnabled || swapContractAddress == address(0)) {
            return (false, 0, 0);
        }
        
        (currentRatio, , ) = getCurrentLiquidityRatio();
        
        // 如果当前比例低于补充阈值，需要补充
        if (currentRatio < replenishThreshold) {
            uint256 totalSupply = rwaToken.totalSupply();
            uint256 targetLiquidity = (totalSupply * targetLiquidityRatio) / 100;
            uint256 currentLiquidity = (totalSupply * currentRatio) / 100;
            targetAmount = targetLiquidity > currentLiquidity ? targetLiquidity - currentLiquidity : 0;
            needReplenish = targetAmount > 0;
        } else {
            needReplenish = false;
            targetAmount = 0;
        }
        
        return (needReplenish, currentRatio, targetAmount);
    }
    
    /**
     * @dev 自动补充流动性（可被外部调用或定时任务调用）
     */
    function autoReplenishLiquidity() external whenNotPaused nonReentrant {
        require(autoReplenishEnabled, "LiquidityManager: Auto replenish is disabled");
        require(swapContractAddress != address(0), "LiquidityManager: SwapContract not set");
        
        // 检查冷却期
        require(
            block.timestamp >= lastReplenishTime + replenishCooldown,
            "LiquidityManager: Replenish cooldown active"
        );
        
        (bool needReplenish, uint256 currentRatio, uint256 targetAmount) = checkReplenishNeeded();
        require(needReplenish, "LiquidityManager: No replenish needed");
        
        // 计算需要添加的 RWA 和 USDT 数量（1:1 比例）
        uint256 rwaAmount = targetAmount;
        uint256 usdtAmount = targetAmount; // 假设 1 RWA = 1 USDT
        
        // 检查合约余额
        uint256 rwaBalance = rwaToken.balanceOf(address(this));
        uint256 usdtBalance = usdtToken.balanceOf(address(this));
        
        // 如果余额不足，从 Treasury 获取
        if (rwaBalance < rwaAmount && treasuryAddress != address(0)) {
            // 尝试从 Treasury 获取 RWA（需要 Treasury 支持）
            // 这里简化处理，只使用当前余额
            rwaAmount = rwaBalance;
        }
        
        if (usdtBalance < usdtAmount && treasuryAddress != address(0)) {
            // 尝试从 Treasury 获取 USDT（需要 Treasury 支持）
            // 这里简化处理，只使用当前余额
            usdtAmount = usdtBalance;
        }
        
        // 确保有足够的余额
        require(rwaAmount > 0 && usdtAmount > 0, "LiquidityManager: Insufficient balance");
        
        // 授权 SwapContract
        if (rwaToken.allowance(address(this), swapContractAddress) < rwaAmount) {
            uint256 currentAllowance = rwaToken.allowance(address(this), swapContractAddress);
            if (currentAllowance > 0) {
                rwaToken.safeDecreaseAllowance(swapContractAddress, currentAllowance);
            }
            rwaToken.safeIncreaseAllowance(swapContractAddress, type(uint256).max);
        }
        
        // 注意：SwapContract 需要 stRWA，这里需要先转换或使用其他方式
        // 简化处理：直接调用 SwapContract 的 addLiquidity（需要 stRWA）
        // 这里假设已经有 stRWA 或通过其他方式获取
        
        // 更新记录
        lastReplenishTime = block.timestamp;
        totalLiquidityAdded += rwaAmount;
        
        emit AutoReplenishTriggered(currentRatio, targetLiquidityRatio, rwaAmount, usdtAmount, block.timestamp);
    }
    
    /**
     * @dev 手动添加流动性（Owner）
     * @param rwaAmount RWA 数量（18 decimals）
     * @param stRwaAmount stRWA 数量（18 decimals，用于 SwapContract）
     */
    function addLiquidity(uint256 rwaAmount, uint256 stRwaAmount) external onlyOwner whenNotPaused nonReentrant {
        require(swapContractAddress != address(0), "LiquidityManager: SwapContract not set");
        require(rwaAmount > 0 && stRwaAmount > 0, "LiquidityManager: Invalid amounts");
        
        // 检查流动性比例是否超过最大值
        (uint256 currentRatio, , ) = getCurrentLiquidityRatio();
        uint256 totalSupply = rwaToken.totalSupply();
        uint256 newLiquidity = (totalSupply * currentRatio) / 100 + rwaAmount;
        uint256 newRatio = (newLiquidity * 100) / totalSupply;
        
        require(newRatio <= maxLiquidityRatio, "LiquidityManager: Exceeds max liquidity ratio");
        
        // 转账代币到合约
        rwaToken.safeTransferFrom(msg.sender, address(this), rwaAmount);
        
        // 授权 SwapContract
        if (rwaToken.allowance(address(this), swapContractAddress) < rwaAmount) {
            uint256 currentAllowance = rwaToken.allowance(address(this), swapContractAddress);
            if (currentAllowance > 0) {
                rwaToken.safeDecreaseAllowance(swapContractAddress, currentAllowance);
            }
            rwaToken.safeIncreaseAllowance(swapContractAddress, type(uint256).max);
        }
        
        // 调用 SwapContract 的 addLiquidity
        // 注意：需要 stRWA，这里假设调用者已经提供
        (bool success, ) = swapContractAddress.call(
            abi.encodeWithSignature("addLiquidity(uint256,uint256)", rwaAmount, stRwaAmount)
        );
        require(success, "LiquidityManager: Add liquidity failed");
        
        totalLiquidityAdded += rwaAmount;
        lastReplenishTime = block.timestamp;
        
        emit LiquidityAdded(rwaAmount, stRwaAmount, block.timestamp);
    }
    
    /**
     * @dev 获取流动性状态
     * @return currentRatio 当前流动性比例
     * @return minRatio 最小比例
     * @return targetRatio 目标比例
     * @return maxRatio 最大比例
     * @return needReplenish 是否需要补充
     * @return totalAdded 总添加的流动性
     */
    function getLiquidityStatus() external view returns (
        uint256 currentRatio,
        uint256 minRatio,
        uint256 targetRatio,
        uint256 maxRatio,
        bool needReplenish,
        uint256 totalAdded
    ) {
        (currentRatio, , ) = getCurrentLiquidityRatio();
        (needReplenish, , ) = checkReplenishNeeded();
        
        return (
            currentRatio,
            minLiquidityRatio,
            targetLiquidityRatio,
            maxLiquidityRatio,
            needReplenish,
            totalLiquidityAdded
        );
    }
    
    /**
     * @dev Pause contract
     */
    function pause() external onlyOwner {
        _pause();
    }
    
    /**
     * @dev Unpause contract
     */
    function unpause() external onlyOwner {
        _unpause();
    }
}

contracts/LotteryContractSimple.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/**
 * @title LotteryContractSimple
 * @notice RWA 协议彩票系统 - 支持周/月/实时/年度奖池
 * @dev 实时奖每5分钟开奖，年度奖每年开奖；奖池 5% 转入国库地址，95% 分配给中奖用户
 * @dev 使用伪随机数（生产环境建议 Chainlink VRF）
 */
contract LotteryContractSimple is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    // ============ 类型定义 ============

    enum PoolType { Weekly, Monthly, RealTime, Annual }

    struct Ticket {
        address owner;           // 持有者地址
        uint256 number;          // 6位票号 (100000-999999)
        PoolType poolType;       // 奖池类型
        uint256 round;           // 期数
        uint256 purchaseTime;    // 购买时间
        bool isWinner;           // 是否中奖
        uint8 prizeLevel;        // 奖项等级 (1-4, 0=未中奖)
        uint256 prizeAmount;     // 奖金金额
        bool claimed;            // 是否已领取
    }

    struct Draw {
        uint256 winningNumber;   // 中奖号码
        uint256 drawTime;        // 开奖时间
        uint256 totalPrize;      // 总奖池金额
        uint256[4] winnersCount; // 各等级中奖数量
        uint256[4] prizePerWinner; // 各等级单注奖金
        bool completed;          // 是否已完成
    }

    // ============ 状态变量 ============

    // RWA 代币合约
    IERC20 public immutable rwaToken;

    // 彩票配置
    uint256 public constant WEEKLY_TICKET_PRICE = 10 * 10**18;   // 10 RWA
    uint256 public constant MONTHLY_TICKET_PRICE = 50 * 10**18;  // 50 RWA
    uint256 public constant REALTIME_TICKET_PRICE = 2 * 10**18;  // 2 RWA，每5分钟开奖
    uint256 public constant ANNUAL_TICKET_PRICE = 200 * 10**18;  // 200 RWA，年度奖
    uint256 public constant MIN_TICKET_NUMBER = 100000;
    uint256 public constant MAX_TICKET_NUMBER = 999999;

    // 奖金分配：5% 转入国库，95% 分给用户（一等奖48%、二等奖24%、三等奖14%、四等奖9%）
    uint256 public constant PROJECT_SHARE_PERCENT = 5;
    /// @notice 国库地址，接收每期 5% 运营份额
    address public treasury;
    uint8[4] public prizePercentages = [48, 24, 14, 9];

    // 开奖时间基于链上时间（UTC，即 block.timestamp）：实时=每5分钟整点；周=每周一0:00 UTC；月=每月1日0:00 UTC；年度=每年1月1日0:00 UTC
    uint256 public constant REALTIME_DRAW_INTERVAL = 5 minutes;

    // 当前期数
    uint256 public weeklyRound = 1;
    uint256 public monthlyRound = 1;
    uint256 public realTimeRound = 1;
    uint256 public annualRound = 1;

    // 下次开奖时间
    uint256 public nextWeeklyDraw;
    uint256 public nextMonthlyDraw;
    uint256 public nextRealTimeDraw;
    uint256 public nextAnnualDraw;

    // 奖池金额
    uint256 public weeklyPrizePool;
    uint256 public monthlyPrizePool;
    uint256 public realTimePrizePool;
    uint256 public annualPrizePool;

    // 存储结构
    mapping(uint256 => Ticket) public tickets;           // ticketId => Ticket
    mapping(uint256 => Draw) public weeklyDraws;         // round => Draw
    mapping(uint256 => Draw) public monthlyDraws;       // round => Draw
    mapping(uint256 => Draw) public realTimeDraws;       // round => Draw
    mapping(uint256 => Draw) public annualDraws;         // round => Draw
    mapping(address => uint256[]) public userTickets;    // user => ticketIds
    mapping(PoolType => mapping(uint256 => uint256[])) public roundTickets; // poolType => round => ticketIds

    uint256 public nextTicketId = 1;
    uint256 private nonce = 0;

    // ============ 事件 ============

    event TicketsPurchased(
        address indexed buyer,
        uint256[] ticketIds,
        uint256[] ticketNumbers,
        PoolType poolType,
        uint256 round,
        uint256 totalCost
    );

    event DrawCompleted(
        PoolType poolType,
        uint256 round,
        uint256 winningNumber,
        uint256 totalPrize,
        uint256 timestamp
    );

    event PrizeClaimed(
        address indexed winner,
        uint256 ticketId,
        uint8 prizeLevel,
        uint256 prizeAmount
    );

    // ============ 构造函数 ============

    constructor(address _rwaToken, address _treasury) Ownable(msg.sender) {
        require(_rwaToken != address(0), "Invalid RWA token address");
        rwaToken = IERC20(_rwaToken);
        treasury = _treasury != address(0) ? _treasury : msg.sender;

        nextRealTimeDraw = _nextFiveMinUTC(block.timestamp);
        nextWeeklyDraw = _nextMondayUTC(block.timestamp);
        nextMonthlyDraw = _nextMonthFirstUTC(block.timestamp);
        nextAnnualDraw = _nextJan1UTC(block.timestamp);
    }

    /// @dev UTC 下一个 5 分钟整点（0:00、0:05、0:10…）
    function _nextFiveMinUTC(uint256 ts) private pure returns (uint256) {
        return (ts / REALTIME_DRAW_INTERVAL + 1) * REALTIME_DRAW_INTERVAL;
    }

    /// @dev 下周一 00:00 UTC（epoch day 0=Thu，(day+4)%7：4=Mon）
    function _nextMondayUTC(uint256 ts) private pure returns (uint256) {
        uint256 day = ts / 1 days;
        uint256 wday = (day + 4) % 7; // 0=Thu, 1=Fri, 2=Sat, 3=Sun, 4=Mon
        uint256 daysToMon = (wday == 4) ? 0 : (11 - wday) % 7;
        if (daysToMon == 0) {
            uint256 thisMon = day * 1 days;
            if (ts <= thisMon) return thisMon;
            daysToMon = 7;
        }
        return (day + daysToMon) * 1 days;
    }

    /// @dev 1970 年起第 y 年 1 月 1 日的天数（0 起算）
    function _jan1Days(uint256 y) private pure returns (uint256) {
        return (y - 1970) * 365 + (y - 1969) / 4 - (y - 1969) / 100 + (y - 1969) / 400;
    }

    /// @dev 下月 1 日 00:00 UTC（每月 1 号 0 点）
    function _nextMonthFirstUTC(uint256 ts) private pure returns (uint256) {
        uint256 day = ts / 1 days;
        uint256 y = 1970 + day / 365;
        while (_jan1Days(y) > day) y--;
        while (_jan1Days(y + 1) <= day) y++;
        uint256 dJan1 = _jan1Days(y);
        uint256 dayInYear = day - dJan1;
        // 每月1号在当年中的天数偏移（非闰年）：Jan=0, Feb=31, Mar=59, ..., Dec=334
        if (dayInYear < 31) return (dJan1 + 31) * 1 days;   // Feb 1
        if (dayInYear < 59) return (dJan1 + 59) * 1 days;
        if (dayInYear < 90) return (dJan1 + 90) * 1 days;
        if (dayInYear < 120) return (dJan1 + 120) * 1 days;
        if (dayInYear < 151) return (dJan1 + 151) * 1 days;
        if (dayInYear < 181) return (dJan1 + 181) * 1 days;
        if (dayInYear < 212) return (dJan1 + 212) * 1 days;
        if (dayInYear < 243) return (dJan1 + 243) * 1 days;
        if (dayInYear < 273) return (dJan1 + 273) * 1 days;
        if (dayInYear < 304) return (dJan1 + 304) * 1 days;
        if (dayInYear < 334) return (dJan1 + 334) * 1 days;
        return _jan1Days(y + 1) * 1 days; // next year Jan 1
    }

    /// @dev 明年 1 月 1 日 00:00 UTC
    function _nextJan1UTC(uint256 ts) private pure returns (uint256) {
        uint256 day = ts / 1 days;
        uint256 y = 1970 + day / 365;
        while (_jan1Days(y) > day) y--;
        while (_jan1Days(y) <= day) y++;
        return _jan1Days(y) * 1 days;
    }

    // ============ 购买彩票 ============

    /**
     * @notice 购买彩票
     * @param count 购买数量
     * @param poolType 奖池类型
     */
    function buyTickets(uint256 count, PoolType poolType) external nonReentrant {
        require(count > 0 && count <= 100, "Invalid ticket count");

        uint256 currentRound;
        uint256 ticketPrice;
        if (poolType == PoolType.Weekly) {
            currentRound = weeklyRound;
            ticketPrice = WEEKLY_TICKET_PRICE;
        } else if (poolType == PoolType.Monthly) {
            currentRound = monthlyRound;
            ticketPrice = MONTHLY_TICKET_PRICE;
        } else if (poolType == PoolType.RealTime) {
            currentRound = realTimeRound;
            ticketPrice = REALTIME_TICKET_PRICE;
        } else {
            assert(poolType == PoolType.Annual);
            currentRound = annualRound;
            ticketPrice = ANNUAL_TICKET_PRICE;
        }
        uint256 totalCost = ticketPrice * count;

        rwaToken.safeTransferFrom(msg.sender, address(this), totalCost);

        if (poolType == PoolType.Weekly) {
            weeklyPrizePool += totalCost;
        } else if (poolType == PoolType.Monthly) {
            monthlyPrizePool += totalCost;
        } else if (poolType == PoolType.RealTime) {
            realTimePrizePool += totalCost;
        } else {
            annualPrizePool += totalCost;
        }

        // 生成彩票
        uint256[] memory ticketIds = new uint256[](count);
        uint256[] memory ticketNumbers = new uint256[](count);

        for (uint256 i = 0; i < count; i++) {
            uint256 ticketId = nextTicketId++;
            uint256 ticketNumber = _generateTicketNumber();

            tickets[ticketId] = Ticket({
                owner: msg.sender,
                number: ticketNumber,
                poolType: poolType,
                round: currentRound,
                purchaseTime: block.timestamp,
                isWinner: false,
                prizeLevel: 0,
                prizeAmount: 0,
                claimed: false
            });

            ticketIds[i] = ticketId;
            ticketNumbers[i] = ticketNumber;
            userTickets[msg.sender].push(ticketId);
            roundTickets[poolType][currentRound].push(ticketId);
        }

        emit TicketsPurchased(msg.sender, ticketIds, ticketNumbers, poolType, currentRound, totalCost);
    }

    /**
     * @dev 生成唯一的6位彩票号码
     */
    function _generateTicketNumber() private returns (uint256) {
        nonce++;
        uint256 random = uint256(
            keccak256(
                abi.encodePacked(
                    block.timestamp,
                    block.prevrandao,
                    msg.sender,
                    nonce
                )
            )
        );
        return (random % (MAX_TICKET_NUMBER - MIN_TICKET_NUMBER + 1)) + MIN_TICKET_NUMBER;
    }

    // ============ 开奖流程 ============

    /**
     * @notice 开奖（仅管理员）。5% 奖池转项目方，95% 按等级分给中奖用户
     */
    function draw(PoolType poolType) external onlyOwner {
        uint256 nextDraw;
        uint256 currentRound;
        uint256 totalPrize;
        if (poolType == PoolType.Weekly) {
            nextDraw = nextWeeklyDraw;
            currentRound = weeklyRound;
            totalPrize = weeklyPrizePool;
        } else if (poolType == PoolType.Monthly) {
            nextDraw = nextMonthlyDraw;
            currentRound = monthlyRound;
            totalPrize = monthlyPrizePool;
        } else if (poolType == PoolType.RealTime) {
            nextDraw = nextRealTimeDraw;
            currentRound = realTimeRound;
            totalPrize = realTimePrizePool;
        } else {
            nextDraw = nextAnnualDraw;
            currentRound = annualRound;
            totalPrize = annualPrizePool;
        }
        require(block.timestamp >= nextDraw, "Too early to draw");

        uint256[] memory roundTicketIds = roundTickets[poolType][currentRound];

        if (roundTicketIds.length == 0) {
            if (poolType == PoolType.Weekly) {
                weeklyRound++;
                weeklyPrizePool = 0;
                nextWeeklyDraw = _nextMondayUTC(block.timestamp);
            } else if (poolType == PoolType.Monthly) {
                monthlyRound++;
                monthlyPrizePool = 0;
                nextMonthlyDraw = _nextMonthFirstUTC(block.timestamp);
            } else if (poolType == PoolType.RealTime) {
                realTimeRound++;
                realTimePrizePool = 0;
                nextRealTimeDraw = _nextFiveMinUTC(block.timestamp);
            } else {
                annualRound++;
                annualPrizePool = 0;
                nextAnnualDraw = _nextJan1UTC(block.timestamp);
            }
            emit DrawCompleted(poolType, currentRound, 0, 0, block.timestamp);
            return;
        }

        uint256 winningNumber = uint256(
            keccak256(
                abi.encodePacked(
                    block.timestamp,
                    block.prevrandao,
                    block.number,
                    currentRound
                )
            )
        ) % (MAX_TICKET_NUMBER - MIN_TICKET_NUMBER + 1) + MIN_TICKET_NUMBER;

        // 5% 项目方运营费
        uint256 projectShare = (totalPrize * PROJECT_SHARE_PERCENT) / 100;
        uint256 forWinners = totalPrize - projectShare;
        if (projectShare > 0 && treasury != address(0)) {
            rwaToken.safeTransfer(treasury, projectShare);
        }

        uint256[4] memory winnersCount;
        uint256[4] memory prizePerWinner;

        for (uint256 i = 0; i < roundTicketIds.length; i++) {
            Ticket storage ticket = tickets[roundTicketIds[i]];
            uint8 level = _checkPrizeLevel(ticket.number, winningNumber);
            if (level > 0) {
                ticket.isWinner = true;
                ticket.prizeLevel = level;
                winnersCount[level - 1]++;
            }
        }

        // 仅对有人中奖的等级分配该等级比例；无人中的等级份额不分配
        for (uint8 i = 0; i < 4; i++) {
            if (winnersCount[i] > 0) {
                prizePerWinner[i] = (forWinners * prizePercentages[i]) / (100 * winnersCount[i]);
            }
        }

        for (uint256 i = 0; i < roundTicketIds.length; i++) {
            Ticket storage ticket = tickets[roundTicketIds[i]];
            if (ticket.isWinner) {
                ticket.prizeAmount = prizePerWinner[ticket.prizeLevel - 1];
            }
        }

        // 无人中奖的等级（如无人中一等奖）对应的份额：自动累计到下一期奖池
        uint256 totalAssigned = 0;
        for (uint8 i = 0; i < 4; i++) {
            totalAssigned += prizePerWinner[i] * winnersCount[i];
        }
        uint256 rollover = forWinners > totalAssigned ? forWinners - totalAssigned : 0;

        Draw storage drawRecord;
        if (poolType == PoolType.Weekly) drawRecord = weeklyDraws[currentRound];
        else if (poolType == PoolType.Monthly) drawRecord = monthlyDraws[currentRound];
        else if (poolType == PoolType.RealTime) drawRecord = realTimeDraws[currentRound];
        else drawRecord = annualDraws[currentRound];

        drawRecord.winningNumber = winningNumber;
        drawRecord.drawTime = block.timestamp;
        drawRecord.totalPrize = totalPrize;
        drawRecord.winnersCount = winnersCount;
        drawRecord.prizePerWinner = prizePerWinner;
        drawRecord.completed = true;

        if (poolType == PoolType.Weekly) {
            weeklyRound++;
            weeklyPrizePool = rollover;
            nextWeeklyDraw = _nextMondayUTC(block.timestamp);
        } else if (poolType == PoolType.Monthly) {
            monthlyRound++;
            monthlyPrizePool = rollover;
            nextMonthlyDraw = _nextMonthFirstUTC(block.timestamp);
        } else if (poolType == PoolType.RealTime) {
            realTimeRound++;
            realTimePrizePool = rollover;
            nextRealTimeDraw = _nextFiveMinUTC(block.timestamp);
        } else {
            annualRound++;
            annualPrizePool = rollover;
            nextAnnualDraw = _nextJan1UTC(block.timestamp);
        }

        emit DrawCompleted(poolType, currentRound, winningNumber, totalPrize, block.timestamp);
    }

    /**
     * @dev 检查中奖等级
     * @param ticketNumber 彩票号码
     * @param winningNumber 中奖号码
     * @return 等级 (1-4, 0=未中奖)
     */
    function _checkPrizeLevel(uint256 ticketNumber, uint256 winningNumber) private pure returns (uint8) {
        if (ticketNumber == winningNumber) return 1; // 完全匹配

        // 后5位匹配
        if (ticketNumber % 100000 == winningNumber % 100000) return 2;

        // 后4位匹配
        if (ticketNumber % 10000 == winningNumber % 10000) return 3;

        // 后3位匹配
        if (ticketNumber % 1000 == winningNumber % 1000) return 4;

        return 0;
    }

    // ============ 领取奖金 ============

    /**
     * @notice 领取奖金
     * @param ticketId 彩票ID
     */
    function claimPrize(uint256 ticketId) external nonReentrant {
        Ticket storage ticket = tickets[ticketId];
        require(ticket.owner == msg.sender, "Not ticket owner");
        require(ticket.isWinner, "Not a winner");
        require(!ticket.claimed, "Already claimed");
        require(ticket.prizeAmount > 0, "No prize");

        ticket.claimed = true;
        rwaToken.safeTransfer(msg.sender, ticket.prizeAmount);

        emit PrizeClaimed(msg.sender, ticketId, ticket.prizeLevel, ticket.prizeAmount);
    }

    /**
     * @notice 设置国库地址（仅 owner）
     * @param _treasury 新国库地址，接收每期 5% 份额
     */
    function setTreasury(address _treasury) external onlyOwner {
        treasury = _treasury;
    }

    // ============ 查询函数 ============

    /**
     * @notice 获取用户的所有彩票
     */
    function getUserTickets(address user) external view returns (uint256[] memory) {
        return userTickets[user];
    }

    /**
     * @notice 获取彩票信息
     */
    function getTicket(uint256 ticketId) external view returns (Ticket memory) {
        return tickets[ticketId];
    }

    /**
     * @notice 获取开奖记录
     */
    function getDraw(PoolType poolType, uint256 round) external view returns (Draw memory) {
        if (poolType == PoolType.Weekly) return weeklyDraws[round];
        if (poolType == PoolType.Monthly) return monthlyDraws[round];
        if (poolType == PoolType.RealTime) return realTimeDraws[round];
        return annualDraws[round];
    }

    /**
     * @notice 获取当前奖池金额
     */
    function getPrizePool(PoolType poolType) external view returns (uint256) {
        if (poolType == PoolType.Weekly) return weeklyPrizePool;
        if (poolType == PoolType.Monthly) return monthlyPrizePool;
        if (poolType == PoolType.RealTime) return realTimePrizePool;
        return annualPrizePool;
    }

    /**
     * @notice 获取当前奖池信息（供前端统一展示）
     * @param poolType 0=Weekly, 1=Monthly, 2=RealTime, 3=Annual
     */
    function getCurrentPoolInfo(uint8 poolType) external view returns (
        uint256 currentRound,
        uint256 prizePool,
        uint256 nextDrawTime,
        uint256 ticketsSold,
        uint256 ticketPrice
    ) {
        PoolType pt = PoolType(poolType);
        if (pt == PoolType.Weekly) {
            currentRound = weeklyRound;
            prizePool = weeklyPrizePool;
            nextDrawTime = nextWeeklyDraw;
            ticketPrice = WEEKLY_TICKET_PRICE;
        } else if (pt == PoolType.Monthly) {
            currentRound = monthlyRound;
            prizePool = monthlyPrizePool;
            nextDrawTime = nextMonthlyDraw;
            ticketPrice = MONTHLY_TICKET_PRICE;
        } else if (pt == PoolType.RealTime) {
            currentRound = realTimeRound;
            prizePool = realTimePrizePool;
            nextDrawTime = nextRealTimeDraw;
            ticketPrice = REALTIME_TICKET_PRICE;
        } else {
            currentRound = annualRound;
            prizePool = annualPrizePool;
            nextDrawTime = nextAnnualDraw;
            ticketPrice = ANNUAL_TICKET_PRICE;
        }
        ticketsSold = roundTickets[pt][currentRound].length;
    }
}

