contracts/PriceStabilizer.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title PriceStabilizer
 * @dev 价格稳定合约 - 价格稳定机制、自动买入/卖出
 * 
 * Features:
 * - 价格稳定机制（目标价格：1 RWA = 1 USDT）
 * - 自动买入/卖出（当价格偏离目标价格时）
 * - 价格保护（最低 0.8 USDT，最高 1.2 USDT）
 * - 与 SwapContract 集成
 */
contract PriceStabilizer is Ownable, Pausable, ReentrancyGuard {
    using SafeERC20 for IERC20;
    
    // Token addresses
    IERC20 public immutable rwaToken;
    IERC20 public immutable usdtToken;
    
    // Contract addresses
    address public swapContractAddress;  // SwapContract 地址
    address public pancakeSwapPair;      // PancakeSwap Pair 地址（可选）
    
    // 价格配置
    uint256 public targetPrice = 1 * 10**18;  // 目标价格：1 RWA = 1 USDT (18 decimals)
    uint256 public priceDeviationThreshold = 10;  // 价格偏差阈值：10%
    uint256 public minPrice = 8 * 10**17;  // 最低价格：0.8 USDT (18 decimals)
    uint256 public maxPrice = 12 * 10**17; // 最高价格：1.2 USDT (18 decimals)
    
    // 自动稳定配置
    bool public autoStabilizeEnabled = true;  // 是否启用自动稳定
    uint256 public stabilizeCooldown = 1 hours; // 稳定冷却期（1小时）
    uint256 public lastStabilizeTime;        // 上次稳定时间
    
    // 交易限制
    uint256 public maxBuyAmount = 10000 * 10**18;  // 单次最大买入金额（RWA）
    uint256 public maxSellAmount = 10000 * 10**18; // 单次最大卖出金额（RWA）
    
    // 统计
    uint256 public totalBuyAmount;   // 总买入金额
    uint256 public totalSellAmount;  // 总卖出金额
    uint256 public stabilizeCount;   // 稳定次数
    
    // 事件
    event PriceStabilized(uint256 currentPrice, uint256 targetPrice, uint256 deviation, bool bought, uint256 amount, uint256 timestamp);
    event BuyExecuted(uint256 usdtAmount, uint256 rwaAmount, uint256 price, uint256 timestamp);
    event SellExecuted(uint256 rwaAmount, uint256 usdtAmount, uint256 price, uint256 timestamp);
    event TargetPriceUpdated(uint256 oldPrice, uint256 newPrice);
    event PriceDeviationThresholdUpdated(uint256 oldThreshold, uint256 newThreshold);
    event MinPriceUpdated(uint256 oldPrice, uint256 newPrice);
    event MaxPriceUpdated(uint256 oldPrice, uint256 newPrice);
    event AutoStabilizeEnabledUpdated(bool enabled);
    event SwapContractAddressUpdated(address indexed oldAddress, address indexed newAddress);
    event PancakeSwapPairUpdated(address indexed oldAddress, address indexed newAddress);
    
    /**
     * @dev Constructor
     * @param _rwaToken RWA token address
     * @param _usdtToken USDT token address
     */
    constructor(address _rwaToken, address _usdtToken) Ownable(msg.sender) {
        require(_rwaToken != address(0), "PriceStabilizer: Invalid RWA token address");
        require(_usdtToken != address(0), "PriceStabilizer: Invalid USDT token address");
        
        rwaToken = IERC20(_rwaToken);
        usdtToken = IERC20(_usdtToken);
    }
    
    /**
     * @dev 设置 SwapContract 地址
     * @param _swapContractAddress SwapContract 地址
     */
    function setSwapContractAddress(address _swapContractAddress) external onlyOwner {
        require(_swapContractAddress != address(0), "PriceStabilizer: Invalid address");
        address oldAddress = swapContractAddress;
        swapContractAddress = _swapContractAddress;
        emit SwapContractAddressUpdated(oldAddress, _swapContractAddress);
    }
    
    /**
     * @dev 设置 PancakeSwap Pair 地址
     * @param _pancakeSwapPair PancakeSwap Pair 地址
     */
    function setPancakeSwapPair(address _pancakeSwapPair) external onlyOwner {
        address oldAddress = pancakeSwapPair;
        pancakeSwapPair = _pancakeSwapPair;
        emit PancakeSwapPairUpdated(oldAddress, _pancakeSwapPair);
    }
    
    /**
     * @dev 设置目标价格
     * @param newPrice 新的目标价格（18 decimals）
     */
    function setTargetPrice(uint256 newPrice) external onlyOwner {
        require(newPrice >= minPrice && newPrice <= maxPrice, "PriceStabilizer: Price out of range");
        uint256 oldPrice = targetPrice;
        targetPrice = newPrice;
        emit TargetPriceUpdated(oldPrice, newPrice);
    }
    
    /**
     * @dev 设置价格偏差阈值
     * @param newThreshold 新的阈值（百分比，10 = 10%）
     */
    function setPriceDeviationThreshold(uint256 newThreshold) external onlyOwner {
        require(newThreshold > 0 && newThreshold <= 50, "PriceStabilizer: Invalid threshold");
        uint256 oldThreshold = priceDeviationThreshold;
        priceDeviationThreshold = newThreshold;
        emit PriceDeviationThresholdUpdated(oldThreshold, newThreshold);
    }
    
    /**
     * @dev 设置最低价格
     * @param newPrice 新的最低价格（18 decimals）
     */
    function setMinPrice(uint256 newPrice) external onlyOwner {
        require(newPrice > 0 && newPrice < targetPrice, "PriceStabilizer: Invalid min price");
        uint256 oldPrice = minPrice;
        minPrice = newPrice;
        emit MinPriceUpdated(oldPrice, newPrice);
    }
    
    /**
     * @dev 设置最高价格
     * @param newPrice 新的最高价格（18 decimals）
     */
    function setMaxPrice(uint256 newPrice) external onlyOwner {
        require(newPrice > targetPrice, "PriceStabilizer: Invalid max price");
        uint256 oldPrice = maxPrice;
        maxPrice = newPrice;
        emit MaxPriceUpdated(oldPrice, newPrice);
    }
    
    /**
     * @dev 设置自动稳定开关
     * @param enabled 是否启用
     */
    function setAutoStabilizeEnabled(bool enabled) external onlyOwner {
        autoStabilizeEnabled = enabled;
        emit AutoStabilizeEnabledUpdated(enabled);
    }
    
    /**
     * @dev 获取当前价格（从 SwapContract 或 PancakeSwap）
     * @return price 当前价格（18 decimals，1 RWA = ? USDT）
     */
    function getCurrentPrice() public view returns (uint256 price) {
        // 优先从 SwapContract 获取价格
        if (swapContractAddress != address(0)) {
            (bool success, bytes memory data) = swapContractAddress.staticcall(
                abi.encodeWithSignature("getPoolStatus()")
            );
            
            if (success && data.length > 0) {
                (uint256 rwaBalance, uint256 stRwaBalance, , ) = abi.decode(data, (uint256, uint256, uint256, uint256));
                
                // 计算价格：price = stRwaBalance / rwaBalance（假设 1 stRWA = 1 USDT）
                if (rwaBalance > 0) {
                    // 价格 = stRwaBalance / rwaBalance * 1e18
                    price = (stRwaBalance * 1e18) / rwaBalance;
                    return price;
                }
            }
        }
        
        // 如果 SwapContract 不可用，尝试从 PancakeSwap 获取
        // 这里简化处理，返回目标价格作为默认值
        return targetPrice;
    }
    
    /**
     * @dev 计算价格偏差
     * @param currentPrice 当前价格
     * @param targetPrice_ 目标价格
     * @return deviation 偏差百分比（10 = 10%）
     */
    function calculateDeviation(uint256 currentPrice, uint256 targetPrice_) public pure returns (uint256 deviation) {
        if (targetPrice_ == 0) {
            return 100; // 如果目标价格为0，返回100%偏差
        }
        
        if (currentPrice >= targetPrice_) {
            // 价格高于目标价格
            deviation = ((currentPrice - targetPrice_) * 100) / targetPrice_;
        } else {
            // 价格低于目标价格
            deviation = ((targetPrice_ - currentPrice) * 100) / targetPrice_;
        }
        
        return deviation;
    }
    
    /**
     * @dev 检查是否需要稳定价格
     * @return needStabilize 是否需要稳定
     * @return currentPrice 当前价格
     * @return deviation 价格偏差
     * @return shouldBuy 是否应该买入（true = 买入，false = 卖出）
     */
    function checkStabilizeNeeded() public view returns (
        bool needStabilize,
        uint256 currentPrice,
        uint256 deviation,
        bool shouldBuy
    ) {
        currentPrice = getCurrentPrice();
        deviation = calculateDeviation(currentPrice, targetPrice);
        
        // 检查价格是否在保护范围内
        if (currentPrice < minPrice || currentPrice > maxPrice) {
            needStabilize = true;
            shouldBuy = currentPrice < minPrice; // 价格过低时买入
            return (needStabilize, currentPrice, deviation, shouldBuy);
        }
        
        // 检查偏差是否超过阈值
        if (deviation > priceDeviationThreshold) {
            needStabilize = true;
            shouldBuy = currentPrice < targetPrice; // 价格低于目标时买入
        } else {
            needStabilize = false;
            shouldBuy = false;
        }
        
        return (needStabilize, currentPrice, deviation, shouldBuy);
    }
    
    /**
     * @dev 稳定价格（自动买入/卖出）
     */
    function stabilizePrice() external whenNotPaused nonReentrant {
        require(autoStabilizeEnabled, "PriceStabilizer: Auto stabilize is disabled");
        require(swapContractAddress != address(0), "PriceStabilizer: SwapContract not set");
        
        // 检查冷却期
        require(
            block.timestamp >= lastStabilizeTime + stabilizeCooldown,
            "PriceStabilizer: Stabilize cooldown active"
        );
        
        (bool needStabilize, uint256 currentPrice, uint256 deviation, bool shouldBuy) = checkStabilizeNeeded();
        require(needStabilize, "PriceStabilizer: No stabilize needed");
        
        if (shouldBuy) {
            // 价格过低，买入RWA提升价格
            uint256 buyAmount = calculateBuyAmount(currentPrice, targetPrice);
            buyAmount = buyAmount > maxBuyAmount ? maxBuyAmount : buyAmount;
            
            if (buyAmount > 0) {
                buyRWA(buyAmount);
            }
        } else {
            // 价格过高，卖出RWA降低价格
            uint256 sellAmount = calculateSellAmount(currentPrice, targetPrice);
            sellAmount = sellAmount > maxSellAmount ? maxSellAmount : sellAmount;
            
            if (sellAmount > 0) {
                sellRWA(sellAmount);
            }
        }
        
        lastStabilizeTime = block.timestamp;
        stabilizeCount++;
        
        emit PriceStabilized(currentPrice, targetPrice, deviation, shouldBuy, shouldBuy ? calculateBuyAmount(currentPrice, targetPrice) : calculateSellAmount(currentPrice, targetPrice), block.timestamp);
    }
    
    /**
     * @dev 计算买入金额
     * @param currentPrice 当前价格
     * @param targetPrice_ 目标价格
     * @return amount 需要买入的USDT金额（6 decimals）
     */
    function calculateBuyAmount(uint256 currentPrice, uint256 targetPrice_) public view returns (uint256 amount) {
        // 简化计算：根据价格偏差计算买入金额
        uint256 deviation = calculateDeviation(currentPrice, targetPrice_);
        
        // 偏差越大，买入金额越大
        // 基础买入金额：1000 USDT
        uint256 baseAmount = 1000 * 10**6; // 1000 USDT (6 decimals)
        amount = (baseAmount * deviation) / priceDeviationThreshold;
        
        // 限制最大买入金额
        uint256 maxUsdtAmount = maxBuyAmount / 1e12; // 转换为6 decimals
        if (amount > maxUsdtAmount) {
            amount = maxUsdtAmount;
        }
        
        return amount;
    }
    
    /**
     * @dev 计算卖出金额
     * @param currentPrice 当前价格
     * @param targetPrice_ 目标价格
     * @return amount 需要卖出的RWA金额（18 decimals）
     */
    function calculateSellAmount(uint256 currentPrice, uint256 targetPrice_) public view returns (uint256 amount) {
        // 简化计算：根据价格偏差计算卖出金额
        uint256 deviation = calculateDeviation(currentPrice, targetPrice_);
        
        // 偏差越大，卖出金额越大
        // 基础卖出金额：1000 RWA
        uint256 baseAmount = 1000 * 10**18; // 1000 RWA (18 decimals)
        amount = (baseAmount * deviation) / priceDeviationThreshold;
        
        // 限制最大卖出金额
        if (amount > maxSellAmount) {
            amount = maxSellAmount;
        }
        
        return amount;
    }
    
    /**
     * @dev 买入RWA（提升价格）
     * @param usdtAmount USDT 金额（6 decimals）
     */
    function buyRWA(uint256 usdtAmount) internal {
        require(usdtAmount > 0, "PriceStabilizer: Invalid amount");
        
        // 检查合约USDT余额
        uint256 usdtBalance = usdtToken.balanceOf(address(this));
        require(usdtBalance >= usdtAmount, "PriceStabilizer: Insufficient USDT balance");
        
        // 通过 SwapContract 买入 RWA（使用 USDT 购买 RWA）
        // 注意：SwapContract 使用 stRWA，这里需要先转换为 stRWA 或直接使用 RWA/USDT 交易对
        // 简化处理：假设可以直接通过 SwapContract 或 PancakeSwap 买入
        
        // 授权 SwapContract
        uint256 currentAllowance = usdtToken.allowance(address(this), swapContractAddress);
        if (currentAllowance < usdtAmount) {
            if (currentAllowance > 0) {
                usdtToken.safeDecreaseAllowance(swapContractAddress, currentAllowance);
            }
            usdtToken.safeIncreaseAllowance(swapContractAddress, type(uint256).max);
        }
        
        // 调用 SwapContract 的 swapRWAToStRWA（反向操作，用 USDT 买入 RWA）
        // 注意：这里需要根据实际的 SwapContract 接口调整
        // 简化处理：假设有直接买入RWA的方法
        
        // 记录统计
        totalBuyAmount += usdtAmount;
        
        emit BuyExecuted(usdtAmount, 0, getCurrentPrice(), block.timestamp);
    }
    
    /**
     * @dev 卖出RWA（降低价格）
     * @param rwaAmount RWA 金额（18 decimals）
     */
    function sellRWA(uint256 rwaAmount) internal {
        require(rwaAmount > 0, "PriceStabilizer: Invalid amount");
        
        // 检查合约RWA余额
        uint256 rwaBalance = rwaToken.balanceOf(address(this));
        require(rwaBalance >= rwaAmount, "PriceStabilizer: Insufficient RWA balance");
        
        // 通过 SwapContract 卖出 RWA（换取 USDT）
        // 授权 SwapContract
        uint256 currentAllowance = rwaToken.allowance(address(this), swapContractAddress);
        if (currentAllowance < rwaAmount) {
            if (currentAllowance > 0) {
                rwaToken.safeDecreaseAllowance(swapContractAddress, currentAllowance);
            }
            rwaToken.safeIncreaseAllowance(swapContractAddress, type(uint256).max);
        }
        
        // 调用 SwapContract 的 swapStRWAToRWA（反向操作，卖出 RWA 换取 stRWA/USDT）
        // 注意：这里需要根据实际的 SwapContract 接口调整
        
        // 记录统计
        totalSellAmount += rwaAmount;
        
        emit SellExecuted(rwaAmount, 0, getCurrentPrice(), block.timestamp);
    }
    
    /**
     * @dev 手动买入RWA（Owner）
     * @param usdtAmount USDT 金额（6 decimals）
     */
    function manualBuy(uint256 usdtAmount) external onlyOwner whenNotPaused nonReentrant {
        require(usdtAmount > 0, "PriceStabilizer: Invalid amount");
        buyRWA(usdtAmount);
    }
    
    /**
     * @dev 手动卖出RWA（Owner）
     * @param rwaAmount RWA 金额（18 decimals）
     */
    function manualSell(uint256 rwaAmount) external onlyOwner whenNotPaused nonReentrant {
        require(rwaAmount > 0, "PriceStabilizer: Invalid amount");
        sellRWA(rwaAmount);
    }
    
    /**
     * @dev 获取价格稳定状态
     * @return currentPrice 当前价格
     * @return targetPrice_ 目标价格
     * @return deviation 价格偏差
     * @return needStabilize 是否需要稳定
     * @return stabilizeCount_ 稳定次数
     */
    function getPriceStabilizeStatus() external view returns (
        uint256 currentPrice,
        uint256 targetPrice_,
        uint256 deviation,
        bool needStabilize,
        uint256 stabilizeCount_
    ) {
        currentPrice = getCurrentPrice();
        targetPrice_ = targetPrice;
        deviation = calculateDeviation(currentPrice, targetPrice);
        (needStabilize, , , ) = checkStabilizeNeeded();
        stabilizeCount_ = stabilizeCount;
        
        return (currentPrice, targetPrice_, deviation, needStabilize, stabilizeCount_);
    }
    
    /**
     * @dev 提取代币（Owner，紧急情况）
     * @param token 代币地址
     * @param amount 提取金额
     */
    function emergencyWithdraw(address token, uint256 amount) external onlyOwner {
        require(token != address(0), "PriceStabilizer: Invalid token address");
        IERC20(token).safeTransfer(owner(), amount);
    }
    
    /**
     * @dev Pause contract
     */
    function pause() external onlyOwner {
        _pause();
    }
    
    /**
     * @dev Unpause contract
     */
    function unpause() external onlyOwner {
        _unpause();
    }
}

contracts/ReferralRewardPool.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

contract ReferralRewardPool is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    IERC20 public immutable usdtToken;
    address public stakingContract;

    struct PendingReward {
        address referrer;
        address referee;
        uint256 stakeAmount;
        uint256 timestamp;
        bool settled;
    }

    PendingReward[] public pendingRewards;
    mapping(address => uint256[]) public userPendingIndexes;
    mapping(address => uint256) public withdrawableBalance;
    uint256 public lastSettlementTime;
    uint256 public constant MIN_WITHDRAWAL = 100 * 10**6;
    uint256 public constant WITHDRAWAL_FEE = 8;

    event RewardRecorded(address indexed referrer, address indexed referee, uint256 stakeAmount, uint256 index);
    event RewardSettled(address indexed referrer, uint256 amount, uint256 count);
    event RewardWithdrawn(address indexed user, uint256 amount, uint256 fee);

    constructor(address _usdtToken, address _stakingContract) Ownable(msg.sender) {
        usdtToken = IERC20(_usdtToken);
        stakingContract = _stakingContract;
        lastSettlementTime = block.timestamp;
    }

    function recordReferralReward(address referrer, address referee, uint256 stakeAmount, uint256, uint8) external {
        require(msg.sender == stakingContract, "Only staking");
        uint256 index = pendingRewards.length;
        pendingRewards.push(PendingReward(referrer, referee, stakeAmount, block.timestamp, false));
        userPendingIndexes[referrer].push(index);
        emit RewardRecorded(referrer, referee, stakeAmount, index);
    }

    function settleWeeklyRewards(address[] calldata referrers, uint8[] calldata levels) external onlyOwner nonReentrant {
        require(referrers.length == levels.length, "Length mismatch");
        for (uint256 i = 0; i < referrers.length; i++) {
            _settleUserRewards(referrers[i], levels[i]);
        }
        lastSettlementTime = block.timestamp;
    }

    function _settleUserRewards(address referrer, uint8 level) internal {
        uint256[] storage indexes = userPendingIndexes[referrer];
        uint256 totalReward = 0;
        uint256 count = 0;

        for (uint256 i = 0; i < indexes.length; i++) {
            PendingReward storage reward = pendingRewards[indexes[i]];
            if (!reward.settled) {
                uint256 rate = _getReferralRewardRate(level);
                totalReward += (reward.stakeAmount * rate) / 10000;
                reward.settled = true;
                count++;
            }
        }

        if (totalReward > 0) {
            withdrawableBalance[referrer] += totalReward;
            emit RewardSettled(referrer, totalReward, count);
        }
    }

    function withdraw(uint256 amount) external nonReentrant {
        require(amount >= MIN_WITHDRAWAL, "Below minimum");
        require(withdrawableBalance[msg.sender] >= amount, "Insufficient balance");

        uint256 fee = (amount * WITHDRAWAL_FEE) / 100;
        uint256 netAmount = amount - fee;

        withdrawableBalance[msg.sender] -= amount;
        usdtToken.safeTransfer(msg.sender, netAmount);
        if (fee > 0) usdtToken.safeTransfer(owner(), fee);

        emit RewardWithdrawn(msg.sender, netAmount, fee);
    }

    function _getReferralRewardRate(uint8 level) internal pure returns (uint256) {
        if (level == 1) return 300;
        if (level == 2) return 500;
        if (level == 3) return 800;
        if (level == 4) return 1200;
        if (level == 5) return 1700;
        if (level == 6) return 2300;
        if (level == 7) return 3000;
        if (level == 8) return 3500;
        if (level == 9) return 4000;
        return 0;
    }

    function getPendingRewards(address user) external view returns (uint256 pending, uint256 withdrawable) {
        uint256[] storage indexes = userPendingIndexes[user];
        for (uint256 i = 0; i < indexes.length; i++) {
            PendingReward storage reward = pendingRewards[indexes[i]];
            if (!reward.settled) {
                pending += reward.stakeAmount;
            }
        }
        withdrawable = withdrawableBalance[user];
    }

    function setStakingContract(address _staking) external onlyOwner {
        stakingContract = _staking;
    }
}

contracts/RWAToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

/**
 * @title RWAToken
 * @dev BEP-20 token with transaction tax mechanism
 * 
 * Features:
 * - Dynamic sell tax: base rate from weighted avg holding (max 4%) + sell-ratio penalty (above 30% of total, 1% per 1%, no cap)
 * - At most 1 sell per 24 hours per address (non-whitelisted)
 * - Buy transactions are tax-free
 * - Whitelist addresses are exempt from tax and 24h limit
 * - Pausable for emergency situations
 */
contract RWAToken is ERC20, Ownable, Pausable {
    // Tax configuration
    uint256 public constant SELL_TAX_RATE = 4; // 4% default when no staking info (base rate max 4%)
    uint256 public constant SELL_RATIO_THRESHOLD = 30; // Sell above 30% of total: each 1% above adds 1% tax
    uint256 public constant SELL_COOLDOWN = 1 days;   // At most 1 sell per 24 hours per address
    uint256 public constant TREASURY_SHARE = 50; // 50% of tax
    uint256 public constant BURN_SHARE = 25; // 25% of tax (5% of total)
    uint256 public constant LIQUIDITY_SHARE = 25; // 25% of tax (5% of total)

    // Addresses (immutable for gas optimization where possible)
    address public immutable treasuryAddress;
    address public immutable liquidityFundAddress;
    address public pancakeSwapPair; // Mutable - can be set after deployment
    address public stakingContract; // StakingContract address for dynamic tax calculation

    // Whitelist (using mapping for Gas optimization)
    mapping(address => bool) public whitelist;
    // Last sell timestamp per address (for 24h cooldown)
    mapping(address => uint256) public lastSellTimestamp;

    // Events
    event TreasuryAddressUpdated(address indexed oldAddress, address indexed newAddress);
    event LiquidityFundAddressUpdated(address indexed oldAddress, address indexed newAddress);
    event PancakeSwapPairUpdated(address indexed oldPair, address indexed newPair);
    event StakingContractUpdated(address indexed oldContract, address indexed newContract);
    event WhitelistUpdated(address indexed account, bool status);
    event TaxCollected(address indexed from, address indexed to, uint256 amount, uint256 taxAmount);
    event DynamicTaxCalculated(address indexed user, uint256 holdingDays, uint256 sellRatio, uint256 baseRate, uint256 finalRate);

    /**
     * @dev Constructor
     * @param _name Token name
     * @param _symbol Token symbol
     * @param _initialSupply Initial token supply (in wei, 18 decimals)
     * @param _treasuryAddress Treasury address for receiving tax
     * @param _liquidityFundAddress Liquidity fund address
     */
    constructor(
        string memory _name,
        string memory _symbol,
        uint256 _initialSupply,
        address _treasuryAddress,
        address _liquidityFundAddress
    ) ERC20(_name, _symbol) Ownable(msg.sender) {
        require(_treasuryAddress != address(0), "Treasury address cannot be zero");
        require(_liquidityFundAddress != address(0), "Liquidity fund address cannot be zero");

        treasuryAddress = _treasuryAddress;
        liquidityFundAddress = _liquidityFundAddress;

        // Mint initial supply to deployer
        _mint(msg.sender, _initialSupply);

        // Add deployer to whitelist
        whitelist[msg.sender] = true;
        whitelist[_treasuryAddress] = true;
        whitelist[_liquidityFundAddress] = true;
    }

    /**
     * @dev Calculate dynamic sell tax rate based on weighted average holding period and sell ratio
     * @param user User address
     * @param sellAmount Sell amount
     * @return taxRate Tax rate in percentage (0-100)
     */
    function calculateDynamicSellTaxRate(address user, uint256 sellAmount) internal view returns (uint256 taxRate) {
        // If staking contract is not set, use default rate
        if (stakingContract == address(0)) {
            return SELL_TAX_RATE; // Default (no staking info)
        }

        // Get user stake info from StakingContract
        (bool success, bytes memory data) = stakingContract.staticcall(
            abi.encodeWithSignature("getUserStakeInfoForTax(address)", user)
        );

        if (!success || data.length == 0) {
            return SELL_TAX_RATE; // Default (cannot read staking info)
        }

        (uint256 totalStaked, uint256 weightedAverageTime) = abi.decode(data, (uint256, uint256));

        // If user has no stake, use default rate
        if (totalStaked == 0) {
            return SELL_TAX_RATE; // Default (non-staker)
        }

        // Calculate weighted average holding days
        uint256 holdingDays = weightedAverageTime / 1 days;

        // Base tax rate from weighted average holding period (max 4%)
        uint256 baseRate;
        if (holdingDays < 30) {
            baseRate = 4;  // 4% for < 30 days
        } else if (holdingDays < 90) {
            baseRate = 3;  // 3% for 30-90 days
        } else if (holdingDays < 180) {
            baseRate = 2;  // 2% for 90-180 days
        } else {
            baseRate = 1;  // 1% for 180+ days
        }

        // Sell ratio = sell amount as % of total staked (user's "总额" = totalStaked)
        uint256 sellRatio = (sellAmount * 100) / totalStaked;

        // Above 30%: each 1% above 30% adds 1% tax (no cap on this penalty)
        uint256 finalRate = baseRate;
        if (sellRatio > SELL_RATIO_THRESHOLD) {
            uint256 additionalTax = sellRatio - SELL_RATIO_THRESHOLD;
            finalRate = baseRate + additionalTax;
            // Cap at 100% so taxAmount never exceeds amount
            if (finalRate > 100) {
                finalRate = 100;
            }
        }

        return finalRate;
    }

    /**
     * @dev Override transfer function to implement dynamic tax logic
     */
    function _update(
        address from,
        address to,
        uint256 amount
    ) internal virtual override whenNotPaused {
        // Check if this is a sell transaction (to PancakeSwap Pair)
        bool isSell = to == pancakeSwapPair && pancakeSwapPair != address(0);

        // Check if sender or receiver is whitelisted
        bool isAddressWhitelisted = whitelist[from] || whitelist[to];

        // Apply tax only on sell transactions from non-whitelisted addresses
        if (isSell && !isAddressWhitelisted && from != address(0) && to != address(0)) {
            // 24h cooldown: at most 1 sell per address per day
            require(
                lastSellTimestamp[from] == 0 || block.timestamp >= lastSellTimestamp[from] + SELL_COOLDOWN,
                "Only one sell per 24h"
            );
            lastSellTimestamp[from] = block.timestamp;

            // Calculate dynamic tax rate
            uint256 taxRate = calculateDynamicSellTaxRate(from, amount);

            uint256 taxAmount;
            uint256 amountAfterTax;
            unchecked {
                taxAmount = (amount * taxRate) / 100;
                amountAfterTax = amount - taxAmount;
            }

            // Calculate tax distribution (optimized: cache calculations)
            uint256 treasuryAmount;
            uint256 burnAmount;
            uint256 liquidityAmount;
            unchecked {
                treasuryAmount = (taxAmount * TREASURY_SHARE) / 100;
                burnAmount = (taxAmount * BURN_SHARE) / 100;
                liquidityAmount = taxAmount - treasuryAmount - burnAmount;
            }

            // Get user stake info for event emission
            uint256 holdingDays = 0;
            uint256 sellRatio = 0;
            if (stakingContract != address(0)) {
                (bool success, bytes memory data) = stakingContract.staticcall(
                    abi.encodeWithSignature("getUserStakeInfoForTax(address)", from)
                );
                if (success && data.length > 0) {
                    (uint256 totalStaked, uint256 weightedAverageTime) = abi.decode(data, (uint256, uint256));
                    if (totalStaked > 0) {
                        holdingDays = weightedAverageTime / 1 days;
                        sellRatio = (amount * 100) / totalStaked;
                    }
                }
            }

            // Transfer to Treasury
            super._update(from, treasuryAddress, treasuryAmount);

            // Burn tokens
            super._update(from, address(0), burnAmount);

            // Transfer to Liquidity Fund
            super._update(from, liquidityFundAddress, liquidityAmount);

            // Transfer remaining amount to recipient
            super._update(from, to, amountAfterTax);

            emit TaxCollected(from, to, amount, taxAmount);
            emit DynamicTaxCalculated(from, holdingDays, sellRatio, taxRate, taxRate);
        } else {
            // No tax applied
            super._update(from, to, amount);
        }
    }

    // Note: treasuryAddress and liquidityFundAddress are now immutable
    // These functions are removed to save gas. If you need to change addresses,
    // you would need to deploy a new contract. This is a security feature.
    // If you need mutable addresses, remove 'immutable' keyword above.

    // Removed setTreasuryAddress and setLiquidityFundAddress functions
    // because addresses are now immutable for gas optimization and security

    /**
     * @dev Set PancakeSwap Pair address
     * @param _pancakeSwapPair PancakeSwap pair address
     */
    function setPancakeSwapPair(address _pancakeSwapPair) external onlyOwner {
        require(_pancakeSwapPair != address(0), "Pair address cannot be zero");
        address oldPair = pancakeSwapPair;
        pancakeSwapPair = _pancakeSwapPair;
        emit PancakeSwapPairUpdated(oldPair, _pancakeSwapPair);
    }

    /**
     * @dev Set StakingContract address for dynamic tax calculation
     * @param _stakingContract StakingContract address
     */
    function setStakingContract(address _stakingContract) external onlyOwner {
        require(_stakingContract != address(0), "StakingContract address cannot be zero");
        address oldContract = stakingContract;
        stakingContract = _stakingContract;
        emit StakingContractUpdated(oldContract, _stakingContract);
    }

    /**
     * @dev Get dynamic sell tax rate for a user (view function)
     * @param user User address
     * @param sellAmount Sell amount
     * @return taxRate Tax rate in percentage (0-100)
     */
    function getDynamicSellTaxRate(address user, uint256 sellAmount) external view returns (uint256 taxRate) {
        return calculateDynamicSellTaxRate(user, sellAmount);
    }

    /**
     * @dev Get next timestamp when user is allowed to sell again (0 = never sold)
     */
    function getNextSellAllowedTime(address user) external view returns (uint256) {
        if (lastSellTimestamp[user] == 0) return 0;
        return lastSellTimestamp[user] + SELL_COOLDOWN;
    }

    /**
     * @dev Add or remove address from whitelist
     * @param account Address to update
     * @param status Whitelist status (true = whitelisted, false = not whitelisted)
     */
    function setWhitelist(address account, bool status) external onlyOwner {
        require(account != address(0), "Cannot whitelist zero address");
        whitelist[account] = status;
        emit WhitelistUpdated(account, status);
    }

    /**
     * @dev Batch update whitelist
     * @param accounts Array of addresses to update
     * @param status Whitelist status for all addresses
     */
    function setWhitelistBatch(address[] calldata accounts, bool status) external onlyOwner {
        for (uint256 i = 0; i < accounts.length; i++) {
            require(accounts[i] != address(0), "Cannot whitelist zero address");
            whitelist[accounts[i]] = status;
            emit WhitelistUpdated(accounts[i], status);
        }
    }

    /**
     * @dev Check if address is whitelisted
     * @param account Address to check
     * @return bool Whitelist status
     */
    function isWhitelisted(address account) external view returns (bool) {
        return whitelist[account];
    }

    /**
     * @dev Pause token transfers (emergency only)
     */
    function pause() external onlyOwner {
        _pause();
    }

    /**
     * @dev Unpause token transfers
     */
    function unpause() external onlyOwner {
        _unpause();
    }

    /**
     * @dev Burn tokens from caller's account
     * @param amount Amount to burn
     */
    function burn(uint256 amount) external {
        _burn(msg.sender, amount);
    }
}

contracts/StakingContract.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "./MetaStakingExtension.sol";

interface IStRWA {
    function burn(address from, uint256 amount) external;
}

interface IReferralRewardPool {
    function recordReferralReward(
        address referrer,
        address referee,
        uint256 stakeAmount,
        uint256 rewardAmount,
        uint8 userLevel
    ) external;
}

/**
 * @title StakingContract
 * @dev Core staking contract for RWA Tokenization Protocol
 * 
 * Features:
 * - 50/50 fund allocation (50% Treasury, 50% Contract). User principal withdrawal pays full amount (100%); when contract 50% is insufficient, admin tops up from treasury.
 * - Permanent referral relationship binding
 * - Unique stakeId generation and tracking
 * - USDT precision conversion (6 decimals to 18 decimals)
 * - Withdrawal with cooldown and fee
 * - Emergency withdrawal mechanism
 */
contract StakingContract is Ownable, Pausable, ReentrancyGuard, MetaStakingExtension {
    using SafeERC20 for IERC20;

    // Token addresses (immutable for gas optimization)
    IERC20 public immutable usdtToken;
    IERC20 public immutable rwaToken;
    IERC20 public stRwaToken; // stRWA 代币地址（可设置，因为需要先部署 StRWA）

    // System addresses (immutable for gas optimization)
    address public immutable treasuryAddress;
    address public immutable backendAddress;
    address public buybackAddress;
    address public referralRewardPool; // 推荐奖励池地址

    // Precision constants
    uint256 private constant USDT_DECIMALS = 6;
    uint256 private constant INTERNAL_DECIMALS = 18;
    uint256 private constant PRECISION_MULTIPLIER = 1e12; // 10^12 (pre-calculated for gas optimization)

    // Withdrawal configuration
    uint256 public constant WITHDRAWAL_FEE_RATE = 8; // 8%
    uint256 public constant BUYBACK_FEE_RATE = 3; // 3%
    uint256 public constant TREASURY_FEE_RATE = 3; // 3%
    uint256 public constant POOL_FEE_RATE = 2; // 2%
    uint256 public constant ST_RWA_LOCK_DURATION = 30 days;
    uint256 public constant WITHDRAWAL_COOLDOWN = 24 hours;
    uint256 public constant MIN_WITHDRAWAL_AMOUNT = 100 * 10 ** INTERNAL_DECIMALS; // 100 tokens (RWA or USDT equivalent)

    // Reward limits
    uint256 public maxRewardPerCall = 10000 * 10 ** INTERNAL_DECIMALS; // 10000 USDT equivalent

    // Multiple cap configuration
    uint256 public constant SINGLE_CAP_MULTIPLIER = 50; // Single reward ≤ staked × 50% (in basis points)
    uint256 public constant DAILY_CAP_MULTIPLIER = 15; // Daily rewards ≤ staked × 15% (in basis points)
    uint256 public constant SOFT_LANDING_THRESHOLD = 45; // Soft landing starts at 45% (in basis points)
    uint256 public constant SOFT_LANDING_REDUCTION_RATE = 2; // 2% reduction per 1% above threshold

    // Global statistics
    uint256 public totalStaked; // Total staked amount (18 decimals)
    uint256 public totalDynamicRewardsPaid; // Total dynamic rewards paid (18 decimals)
    uint256 private stakesCounter; // Auto-increment counter for stakeId

    // Daily reward tracking (user => day => amount)
    // day = block.timestamp / 1 days
    mapping(address => mapping(uint256 => uint256)) public dailyRewards;

    // Stake record for weighted average holding period calculation
    struct StakeRecord {
        uint256 amount;      // Staked amount (18 decimals)
        uint256 timestamp;   // Stake timestamp
    }

    // Lock period mapping: stakeId => lockPeriod (0=flexible, 30, 90, 180, 365 days)
    mapping(uint256 => uint256) public stakeLockPeriods;

    struct USDTLockedPrincipal {
        uint256 stakeId;
        uint256 totalAmount;       // Full original stake amount (18 decimals)
        uint256 principalAmount;   // Refundable principal kept in contract (18 decimals)
        uint256 lockStartTime;
        uint256 lockEndTime;
        bool isWithdrawn;
        uint256 lockPeriod;
    }

    // RWA Staking structures (parallel to USDT staking)
    struct RWAStakeInfo {
        uint256 totalStakedRWA;   // Total staked RWA amount (18 decimals)
        uint256 rwaPending;        // Pending RWA tokens (18 decimals)
        uint256 lastWithdrawTime;  // Last withdrawal timestamp
        address referrer;          // Referrer address
        uint256 firstStakeTime;    // First stake timestamp
        uint8 nodeLevel;           // Node level (1-9)
        bool isActive;             // Whether user has active principal
    }

    struct RWALockedPrincipal {
        uint256 stakeId;           // Stake ID
        uint256 totalAmount;       // Full original stake amount (18 decimals)
        uint256 principalAmount;   // Principal amount (RWA, 18 decimals)
        uint256 lockStartTime;     // Lock start time
        uint256 lockEndTime;       // Lock end time
        bool isWithdrawn;          // Whether withdrawn
        uint256 lockPeriod;        // Lock period in days
    }

    // USDT staking principal tracking
    mapping(address => USDTLockedPrincipal[]) public usdtLockedPrincipals;
    mapping(address => uint256) public usdtFlexiblePrincipal;
    mapping(address => uint256) public usdtFlexibleTotalStaked;

    // RWA Staking mappings
    mapping(address => RWAStakeInfo) public rwaStakes;
    mapping(address => RWALockedPrincipal[]) public rwaLockedPrincipals;
    /// @dev 未锁仓（灵活）合约侧 50% 记账；提现时按全额（totalStaked）支付，不足时由管理员从国库转入
    mapping(address => uint256) public rwaFlexiblePrincipal;
    mapping(address => uint256) public rwaFlexibleTotalStaked;
    uint256 public totalStakedRWA;  // Global total staked RWA

    // User information structure (optimized with packed storage)
    struct UserInfo {
        uint256 totalStaked;        // Total staked amount (18 decimals) - Slot 1
        uint256 rwaPending;         // Pending RWA tokens (18 decimals) - Slot 2
        uint256 usdtRewards;        // Dynamic USDT rewards (18 decimals) - Slot 3
        uint256 lastWithdrawTime;   // Last withdrawal timestamp - Slot 4
        address referrer;           // Referrer address (immutable once set) - Slot 5
        uint256 firstStakeTime;     // First stake timestamp - Slot 6
        uint8 nodeLevel;            // Node level (1-9) - Slot 7 (packed with isActive)
        bool isActive;              // Whether user has active principal - Slot 7 (packed with nodeLevel)
    }

    // Mappings
    mapping(address => UserInfo) public users;
    mapping(uint256 => bool) public processedStakes; // Track processed stakeIds
    mapping(address => bool) public whitelist; // Whitelist for fee exemption
    mapping(address => StakeRecord[]) public stakeHistory; // User stake history for weighted average calculation

    /// @dev 锁仓到期后已对该笔 burn 过 stRWA 的标记，提现时不再重复 burn
    mapping(address => mapping(uint256 => bool)) public usdtMaturedStRwaBurned;
    mapping(address => mapping(uint256 => bool)) public rwaMaturedStRwaBurned;

    // Events
    event StakeEvent(
        address indexed user,
        uint256 amount,
        address indexed referrer,
        uint256 indexed stakeId,
        uint256 timestamp,
        uint256 lockPeriod  // Lock period in days (0=flexible, 30, 90, 180, 365)
    );

    event ReferralBound(
        address indexed user,
        address indexed referrer,
        uint256 timestamp
    );

    event RewardsUpdated(
        address indexed user,
        uint256 rwAmount,
        uint256 usdtAmount,
        uint256 indexed stakeId,
        uint256 timestamp
    );

    event WithdrawalRequested(
        address indexed user,
        uint256 amount,
        uint256 fee,
        uint256 timestamp
    );

    event NodeLevelUpdated(
        address indexed user,
        uint8 oldLevel,
        uint8 newLevel,
        uint256 timestamp
    );

    event EmergencyWithdrawal(
        address indexed user,
        uint256 refundAmount,
        uint256 deductedRewards
    );

    event TreasuryAddressUpdated(address indexed oldAddress, address indexed newAddress);
    event BackendAddressUpdated(address indexed oldAddress, address indexed newAddress);
    event MaxRewardPerCallUpdated(uint256 newLimit);
    event WhitelistUpdated(address indexed account, bool status);
    event BuybackAddressUpdated(address indexed oldAddress, address indexed newAddress);
    event StRWATokenUpdated(address indexed oldToken, address indexed newToken);
    event StRWAMinted(address indexed user, uint256 amount, uint256 timestamp);
    event TokensBurned(uint256 amount, uint256 timestamp);
    event CapCheckFailed(
        address indexed user,
        string capType,
        uint256 limit,
        uint256 requested,
        uint256 timestamp
    );

    // RWA Staking events
    event RWAStakeEvent(
        address indexed user,
        uint256 amount,
        address indexed referrer,
        uint256 indexed stakeId,
        uint256 timestamp,
        uint256 lockPeriod
    );

    event RWAPrincipalWithdrawn(
        address indexed user,
        uint256 indexed lockIndex,
        uint256 amount,
        uint256 timestamp
    );

    event RWARewardWithdrawn(
        address indexed user,
        uint256 amount,
        uint256 fee,
        uint256 timestamp
    );

    event USDTPrincipalWithdrawn(
        address indexed user,
        uint256 indexed lockIndex,
        uint256 grossAmount,
        uint256 netAmount,
        uint256 timestamp
    );

    event FlexibleUSDTPrincipalWithdrawn(
        address indexed user,
        uint256 grossAmount,
        uint256 netAmount,
        uint256 timestamp
    );

    event FlexibleRWAPrincipalWithdrawn(
        address indexed user,
        uint256 amount,
        uint256 timestamp
    );

    /**
     * @dev Constructor
     */
    constructor(
        address _usdtToken,
        address _rwaToken,
        address _treasuryAddress,
        address _backendAddress
    ) Ownable(msg.sender) {
        require(_usdtToken != address(0), "USDT token address cannot be zero");
        require(_rwaToken != address(0), "RWA token address cannot be zero");
        require(_treasuryAddress != address(0), "Treasury address cannot be zero");
        require(_backendAddress != address(0), "Backend address cannot be zero");

        // Immutable variables are assigned directly (stored in code, not storage - saves gas)
        // Note: For immutable variables, we assign them directly in the constructor
        // The compiler will optimize storage - they're stored in the bytecode, not storage slots
        usdtToken = IERC20(_usdtToken);
        rwaToken = IERC20(_rwaToken);
        treasuryAddress = _treasuryAddress;
        backendAddress = _backendAddress;
        buybackAddress = _treasuryAddress;

        // Add system addresses to whitelist
        whitelist[_treasuryAddress] = true;
        whitelist[_backendAddress] = true;
        whitelist[msg.sender] = true;
    }

    function setBuybackAddress(address _buybackAddress) external onlyOwner {
        require(_buybackAddress != address(0), "Buyback address cannot be zero");
        address oldAddress = buybackAddress;
        buybackAddress = _buybackAddress;
        whitelist[_buybackAddress] = true;
        emit BuybackAddressUpdated(oldAddress, _buybackAddress);
    }

    function setReferralRewardPool(address _pool) external onlyOwner {
        require(_pool != address(0), "Invalid pool address");
        referralRewardPool = _pool;
    }

    /**
     * @dev Set stRWA token address (can be set after StRWA deployment)
     * @param _stRwaToken stRWA 代币地址
     */
    function setStRWAToken(address _stRwaToken) external onlyOwner {
        require(_stRwaToken != address(0), "StRWA token address cannot be zero");
        address oldToken = address(stRwaToken);
        stRwaToken = IERC20(_stRwaToken);
        emit StRWATokenUpdated(oldToken, _stRwaToken);
    }

    /**
     * @dev Return the unified referrer for a user.
     * The protocol now treats referrer as a single identity across USDT and RWA staking.
     */
    function _getUnifiedReferrer(address userAddress) internal view returns (address) {
        address userReferrer = users[userAddress].referrer;
        if (userReferrer != address(0)) {
            return userReferrer;
        }
        return rwaStakes[userAddress].referrer;
    }

    /**
     * @dev Bind a single referrer across both staking modes.
     * If one side was historically bound, sync the other side to the same referrer.
     */
    function _bindUnifiedReferrer(address userAddress, address referrer) internal returns (address) {
        UserInfo storage user = users[userAddress];
        RWAStakeInfo storage rwaStake = rwaStakes[userAddress];

        address existingReferrer = user.referrer != address(0) ? user.referrer : rwaStake.referrer;
        if (existingReferrer != address(0)) {
            if (user.referrer == address(0)) {
                user.referrer = existingReferrer;
            }
            if (rwaStake.referrer == address(0)) {
                rwaStake.referrer = existingReferrer;
            }
            return existingReferrer;
        }

        if (referrer == address(0) || referrer == userAddress) {
            return address(0);
        }

        user.referrer = referrer;
        rwaStake.referrer = referrer;
        emit ReferralBound(userAddress, referrer, block.timestamp);
        return referrer;
    }

    function _splitImmediateFee(uint256 grossAmount) internal pure returns (
        uint256 buybackAmount,
        uint256 treasuryAmount,
        uint256 poolAmount,
        uint256 netAmount
    ) {
        buybackAmount = grossAmount * BUYBACK_FEE_RATE / 100;
        treasuryAmount = grossAmount * TREASURY_FEE_RATE / 100;
        poolAmount = grossAmount * POOL_FEE_RATE / 100;
        netAmount = grossAmount - buybackAmount - treasuryAmount - poolAmount;
    }

    function _payoutUsdtImmediate(address user, uint256 grossAmount) internal returns (uint256 netAmount) {
        uint256 buybackAmount;
        uint256 treasuryAmount;
        uint256 poolAmount;
        (buybackAmount, treasuryAmount, poolAmount, netAmount) = _splitImmediateFee(grossAmount);
        poolAmount;

        usdtToken.safeTransfer(user, netAmount / PRECISION_MULTIPLIER);

        if (buybackAmount > 0) {
            usdtToken.safeTransfer(buybackAddress, buybackAmount / PRECISION_MULTIPLIER);
        }

        if (treasuryAmount > 0) {
            usdtToken.safeTransfer(treasuryAddress, treasuryAmount / PRECISION_MULTIPLIER);
        }
    }

    function _payoutRwaImmediate(address user, uint256 grossAmount) internal returns (uint256 netAmount) {
        uint256 buybackAmount;
        uint256 treasuryAmount;
        uint256 poolAmount;
        (buybackAmount, treasuryAmount, poolAmount, netAmount) = _splitImmediateFee(grossAmount);
        poolAmount;

        rwaToken.safeTransfer(user, netAmount);

        if (buybackAmount > 0) {
            rwaToken.safeTransfer(address(0x000000000000000000000000000000000000dEaD), buybackAmount);
        }

        if (treasuryAmount > 0) {
            rwaToken.safeTransfer(treasuryAddress, treasuryAmount);
        }
    }

    function _decreaseUserStakeTotals(
        address userAddress,
        uint256 usdtAmount,
        uint256 rwaAmount
    ) internal {
        UserInfo storage user = users[userAddress];
        RWAStakeInfo storage rwaStakeInfo = rwaStakes[userAddress];

        if (usdtAmount > 0) {
            if (user.totalStaked <= usdtAmount) {
                user.totalStaked = 0;
            } else {
                unchecked {
                    user.totalStaked -= usdtAmount;
                }
            }
        }

        if (rwaAmount > 0) {
            if (rwaStakeInfo.totalStakedRWA <= rwaAmount) {
                rwaStakeInfo.totalStakedRWA = 0;
            } else {
                unchecked {
                    rwaStakeInfo.totalStakedRWA -= rwaAmount;
                }
            }
        }

        user.isActive = user.totalStaked > 0;
        rwaStakeInfo.isActive = rwaStakeInfo.totalStakedRWA > 0;
    }

    function _mintStRWA(address to, uint256 amount, uint256 lockDuration) internal {
        require(address(stRwaToken) != address(0), "StRWA token not set");

        bytes memory data = lockDuration > 0
            ? abi.encodeWithSignature("mintLocked(address,uint256,uint256)", to, amount, lockDuration)
            : abi.encodeWithSignature("mint(address,uint256)", to, amount);

        (bool success, ) = address(stRwaToken).call(data);
        require(success, "StRWA mint failed");
        emit StRWAMinted(to, amount, block.timestamp);
    }

    /// @dev 从 from 销毁 amount 的 stRWA（仅 StakingContract 可调 StRWA.burn）；应销毁量 = 提现金额×50%
    function _burnStRWA(address from, uint256 amount) internal {
        if (address(stRwaToken) == address(0) || amount == 0) return;
        require(IERC20(stRwaToken).balanceOf(from) >= amount, "Insufficient stRWA to burn");
        IStRWA(address(stRwaToken)).burn(from, amount);
    }

    /**
     * @dev Stake USDT tokens
     * @param amount USDT amount (6 decimals)
     * @param referrer Referrer address (optional, only for first stake)
     * @param lockPeriod Lock period in days (0=flexible, 30, 90, 180, 365)
     */
    function stake(uint256 amount, address referrer, uint256 lockPeriod) external nonReentrant whenNotPaused {
        require(amount > 0, "Amount must be greater than zero");
        require(amount >= 100 * 10 ** USDT_DECIMALS, "Minimum stake: 100 USDT");  // Minimum 100 USDT

        // Convert USDT amount to internal precision (6 decimals -> 18 decimals)
        // CRITICAL: Multiply first, then divide to avoid precision loss
        uint256 internalAmount = amount * PRECISION_MULTIPLIER;

        // Generate unique stakeId (unchecked for gas optimization - counter won't overflow)
        uint256 stakeId;
        unchecked {
            stakeId = stakesCounter++;
        }

        // 50/50：灵活与锁仓均为 50% 国库、50% 合约；提现时按全额支付，不足由管理员从国库转入
        uint256 treasuryAmount = internalAmount / 2;
        uint256 contractAmount = internalAmount - treasuryAmount;

        usdtToken.safeTransferFrom(msg.sender, treasuryAddress, treasuryAmount / PRECISION_MULTIPLIER);
        usdtToken.safeTransferFrom(msg.sender, address(this), contractAmount / PRECISION_MULTIPLIER);

        // Store lock period (0=flexible, 30, 90, 180, 365)
        require(lockPeriod == 0 || lockPeriod == 30 || lockPeriod == 90 || lockPeriod == 180 || lockPeriod == 365, "Invalid lock period");
        stakeLockPeriods[stakeId] = lockPeriod;
        // 注意：质押时不再铸造stRWA，只在提现选择stRWA时才铸造

        // Cache user info to reduce storage reads
        UserInfo storage user = users[msg.sender];
        address effectiveReferrer = _bindUnifiedReferrer(msg.sender, referrer);

        // Update user info (optimized: single storage access)
        unchecked {
            user.totalStaked += internalAmount;
        }
        user.isActive = true;

        if (user.firstStakeTime == 0) {
            user.firstStakeTime = block.timestamp;
            user.nodeLevel = 1; // Default to L1
        }

        // Record stake history for weighted average holding period calculation
        stakeHistory[msg.sender].push(StakeRecord({
            amount: internalAmount,
            timestamp: block.timestamp
        }));

        // Update global statistics (unchecked for gas optimization)
        unchecked {
            totalStaked += internalAmount;
        }

        if (lockPeriod > 0) {
            usdtLockedPrincipals[msg.sender].push(USDTLockedPrincipal({
                stakeId: stakeId,
                totalAmount: internalAmount,
                principalAmount: contractAmount,
                lockStartTime: block.timestamp,
                lockEndTime: block.timestamp + (lockPeriod * 1 days),
                isWithdrawn: false,
                lockPeriod: lockPeriod
            }));
        } else {
            unchecked {
                usdtFlexiblePrincipal[msg.sender] += contractAmount;
                usdtFlexibleTotalStaked[msg.sender] += internalAmount;
            }
        }

        // 记录推荐奖励（不立即发放，等待每周结算）
        if (effectiveReferrer != address(0) && referralRewardPool != address(0)) {
            IReferralRewardPool(referralRewardPool).recordReferralReward(
                effectiveReferrer,
                msg.sender,
                internalAmount / PRECISION_MULTIPLIER,
                0,
                0
            );
        }

        // Emit stake event
        emit StakeEvent(msg.sender, internalAmount, effectiveReferrer, stakeId, block.timestamp, lockPeriod);
    }

