    /**
     * @dev Withdraw RWA tokens
     * @param amount Amount to withdraw (18 decimals)
     * @param chooseStRWA If true, mint 120% as 30-day locked stRWA, else immediate withdrawal with 8% fee
     */
    function withdraw(uint256 amount, bool chooseStRWA) public nonReentrant whenNotPaused {
        UserInfo storage user = users[msg.sender];

        // Verify user has sufficient balance
        require(user.rwaPending >= amount, "Insufficient balance");

        // Verify minimum withdrawal amount
        require(amount >= MIN_WITHDRAWAL_AMOUNT, "Below minimum withdrawal amount");

        // Verify cooldown period (24 hours)
        require(
            block.timestamp >= user.lastWithdrawTime + WITHDRAWAL_COOLDOWN,
            "Withdrawal cooldown active"
        );

        // Update user balance
        user.rwaPending -= amount;
        user.lastWithdrawTime = block.timestamp;

        uint256 burnAmount = amount / 2;
        _burnStRWA(msg.sender, burnAmount);

        if (chooseStRWA) {
            uint256 stRwaAmount = (amount * 120) / 100;
            _mintStRWA(msg.sender, stRwaAmount, ST_RWA_LOCK_DURATION);
            emit WithdrawalRequested(msg.sender, amount, 0, block.timestamp);
        } else {
            uint256 netAmount = _payoutRwaImmediate(msg.sender, amount);
            emit WithdrawalRequested(msg.sender, amount, amount - netAmount, block.timestamp);
        }
    }

    /**
     * @dev Withdraw RWA staking rewards stored in rwaStakes[msg.sender].rwaPending
     * Uses the same 24h cooldown as USDT-staking reward withdrawal.
     */
    function withdrawRWARewards(uint256 amount, bool chooseStRWA) external nonReentrant whenNotPaused {
        RWAStakeInfo storage rwaStakeInfo = rwaStakes[msg.sender];

        require(rwaStakeInfo.rwaPending >= amount, "Insufficient RWA staking rewards");
        require(amount >= MIN_WITHDRAWAL_AMOUNT, "Below minimum withdrawal amount");
        require(
            block.timestamp >= rwaStakeInfo.lastWithdrawTime + WITHDRAWAL_COOLDOWN,
            "Withdrawal cooldown active"
        );

        rwaStakeInfo.rwaPending -= amount;
        rwaStakeInfo.lastWithdrawTime = block.timestamp;

        // 注意：不再销毁stRWA，因为质押时没有铸造

        if (chooseStRWA) {
            uint256 stRwaAmount = (amount * 120) / 100;
            _mintStRWA(msg.sender, stRwaAmount, ST_RWA_LOCK_DURATION);
            emit RWARewardWithdrawn(msg.sender, amount, 0, block.timestamp);
        } else {
            uint256 netAmount = _payoutRwaImmediate(msg.sender, amount);
            emit RWARewardWithdrawn(msg.sender, amount, amount - netAmount, block.timestamp);
        }
    }

    /// @dev 灵活 USDT 本金提现：按指定金额（amount = 本次提现的全额本金，18 位）支付并扣手续费，剩余保留在合约；销毁 amount/2 的 stRWA
    function withdrawFlexibleUSDTPrincipal(uint256 amount) external nonReentrant whenNotPaused {
        require(amount >= MIN_WITHDRAWAL_AMOUNT, "Below minimum withdrawal amount");

        // 计算可用余额：灵活期 + 已到期的锁仓
        uint256 flexibleBalance = usdtFlexibleTotalStaked[msg.sender];
        uint256 maturedBalance = 0;

        // 遍历锁仓记录，找出已到期的
        USDTLockedPrincipal[] storage locks = usdtLockedPrincipals[msg.sender];
        for (uint256 i = 0; i < locks.length; i++) {
            if (!locks[i].isWithdrawn && block.timestamp >= locks[i].lockEndTime) {
                maturedBalance += locks[i].principalAmount;
            }
        }

        uint256 totalAvailable = flexibleBalance + maturedBalance;
        require(totalAvailable > 0, "No available principal");
        require(amount <= totalAvailable, "Exceeds available principal");

        // 先从灵活期扣除
        if (flexibleBalance >= amount) {
            usdtFlexiblePrincipal[msg.sender] -= amount / 2;
            usdtFlexibleTotalStaked[msg.sender] -= amount;
        } else {
            // 灵活期不足，从已到期的锁仓扣除
            if (flexibleBalance > 0) {
                usdtFlexiblePrincipal[msg.sender] = 0;
                usdtFlexibleTotalStaked[msg.sender] = 0;
            }

            uint256 remaining = amount - flexibleBalance;
            // 从已到期的锁仓中扣除
            for (uint256 i = 0; i < locks.length && remaining > 0; i++) {
                if (!locks[i].isWithdrawn && block.timestamp >= locks[i].lockEndTime) {
                    if (locks[i].principalAmount <= remaining) {
                        remaining -= locks[i].principalAmount;
                        locks[i].isWithdrawn = true;
                    } else {
                        locks[i].principalAmount -= remaining;
                        locks[i].totalAmount -= remaining;
                        remaining = 0;
                    }
                }
            }
        }

        _decreaseUserStakeTotals(msg.sender, amount, 0);

        // 注意：不再销毁stRWA，因为质押时没有铸造

        uint256 netAmount = _payoutUsdtImmediate(msg.sender, amount);
        emit FlexibleUSDTPrincipalWithdrawn(msg.sender, amount, netAmount, block.timestamp);
    }

    function withdrawUSDTPrincipal(uint256 lockIndex) external nonReentrant whenNotPaused {
        USDTLockedPrincipal storage lockedPrincipal = usdtLockedPrincipals[msg.sender][lockIndex];
        require(!lockedPrincipal.isWithdrawn, "Principal already withdrawn");
        require(block.timestamp >= lockedPrincipal.lockEndTime, "Still locked");
        require(lockedPrincipal.principalAmount >= MIN_WITHDRAWAL_AMOUNT, "Below minimum withdrawal amount");

        // 注意：不再销毁stRWA，因为质押时没有铸造

        lockedPrincipal.isWithdrawn = true;
        _decreaseUserStakeTotals(msg.sender, lockedPrincipal.totalAmount, 0);

        uint256 netAmount = _payoutUsdtImmediate(msg.sender, lockedPrincipal.principalAmount);
        emit USDTPrincipalWithdrawn(msg.sender, lockIndex, lockedPrincipal.principalAmount, netAmount, block.timestamp);
    }

    /// @dev 灵活 RWA 本金提现：按指定金额（amount = 本次提现的全额本金，18 位）支付并扣手续费，剩余保留在合约；销毁 amount/2 的 stRWA
    function withdrawFlexibleRWAPrincipal(uint256 amount) external nonReentrant whenNotPaused {
        require(amount >= MIN_WITHDRAWAL_AMOUNT, "Below minimum withdrawal amount");

        // 计算可用余额：灵活期 + 已到期的锁仓
        uint256 flexibleBalance = rwaFlexibleTotalStaked[msg.sender];
        uint256 maturedBalance = 0;

        RWALockedPrincipal[] storage locks = rwaLockedPrincipals[msg.sender];
        for (uint256 i = 0; i < locks.length; i++) {
            if (!locks[i].isWithdrawn && block.timestamp >= locks[i].lockEndTime) {
                maturedBalance += locks[i].principalAmount;
            }
        }

        uint256 totalAvailable = flexibleBalance + maturedBalance;
        require(totalAvailable > 0, "No available principal");
        require(amount <= totalAvailable, "Exceeds available principal");

        if (flexibleBalance >= amount) {
            rwaFlexiblePrincipal[msg.sender] -= amount / 2;
            rwaFlexibleTotalStaked[msg.sender] -= amount;
        } else {
            if (flexibleBalance > 0) {
                rwaFlexiblePrincipal[msg.sender] = 0;
                rwaFlexibleTotalStaked[msg.sender] = 0;
            }

            uint256 remaining = amount - flexibleBalance;
            for (uint256 i = 0; i < locks.length && remaining > 0; i++) {
                if (!locks[i].isWithdrawn && block.timestamp >= locks[i].lockEndTime) {
                    if (locks[i].principalAmount <= remaining) {
                        remaining -= locks[i].principalAmount;
                        locks[i].isWithdrawn = true;
                    } else {
                        locks[i].principalAmount -= remaining;
                        locks[i].totalAmount -= remaining;
                        remaining = 0;
                    }
                }
            }
        }

        _decreaseUserStakeTotals(msg.sender, 0, amount);

        // 注意：不再销毁stRWA，因为质押时没有铸造

        uint256 netAmount = _payoutRwaImmediate(msg.sender, amount);
        emit FlexibleRWAPrincipalWithdrawn(msg.sender, netAmount, block.timestamp);
    }

    function withdrawRWALockedPrincipal(uint256 lockIndex, bool chooseStRWA) external nonReentrant whenNotPaused {
        RWALockedPrincipal storage lockedPrincipal = rwaLockedPrincipals[msg.sender][lockIndex];
        require(!lockedPrincipal.isWithdrawn, "Principal already withdrawn");
        require(block.timestamp >= lockedPrincipal.lockEndTime, "Still locked");
        require(lockedPrincipal.principalAmount >= MIN_WITHDRAWAL_AMOUNT, "Below minimum withdrawal amount");

        // 注意：不再销毁stRWA，因为质押时没有铸造

        lockedPrincipal.isWithdrawn = true;
        _decreaseUserStakeTotals(msg.sender, 0, lockedPrincipal.totalAmount);

        if (chooseStRWA) {
            uint256 stRwaAmount = (lockedPrincipal.principalAmount * 120) / 100;
            _mintStRWA(msg.sender, stRwaAmount, ST_RWA_LOCK_DURATION);
            emit RWAPrincipalWithdrawn(msg.sender, lockIndex, stRwaAmount, block.timestamp);
        } else {
            uint256 netAmount = _payoutRwaImmediate(msg.sender, lockedPrincipal.principalAmount);
            emit RWAPrincipalWithdrawn(msg.sender, lockIndex, netAmount, block.timestamp);
        }
    }

    /// @dev 锁仓到期后由任何人调用，从 user 销毁该笔 USDT 锁仓对应的 stRWA（本金×50%），之后 user 提现本金时不再 burn
    function processMaturedStakeUSDT(address user, uint256 lockIndex) external nonReentrant whenNotPaused {
        USDTLockedPrincipal storage lockedPrincipal = usdtLockedPrincipals[user][lockIndex];
        require(block.timestamp >= lockedPrincipal.lockEndTime, "Not matured");
        require(!lockedPrincipal.isWithdrawn, "Already withdrawn");
        require(!usdtMaturedStRwaBurned[user][lockIndex], "stRWA already burned for this position");

        uint256 burnAmount = lockedPrincipal.principalAmount / 2;
        _burnStRWA(user, burnAmount);
        usdtMaturedStRwaBurned[user][lockIndex] = true;
    }

    /// @dev 锁仓到期后由任何人调用，从 user 销毁该笔 RWA 锁仓对应的 stRWA（本金×50%），之后 user 提现本金时不再 burn
    function processMaturedStakeRWA(address user, uint256 lockIndex) external nonReentrant whenNotPaused {
        RWALockedPrincipal storage lockedPrincipal = rwaLockedPrincipals[user][lockIndex];
        require(block.timestamp >= lockedPrincipal.lockEndTime, "Not matured");
        require(!lockedPrincipal.isWithdrawn, "Already withdrawn");
        require(!rwaMaturedStRwaBurned[user][lockIndex], "stRWA already burned for this position");

        uint256 burnAmount = lockedPrincipal.principalAmount / 2;
        _burnStRWA(user, burnAmount);
        rwaMaturedStRwaBurned[user][lockIndex] = true;
    }

    /**
     * @dev Check global cap with soft landing mechanism
     * @param newReward New reward amount to add
     * @return allowed Whether the reward is allowed
     * @return adjustedReward Adjusted reward amount after soft landing
     */
    function checkGlobalCap(uint256 newReward) internal view returns (bool allowed, uint256 adjustedReward) {
        uint256 maxAllowedRewards = totalStaked / 2; // 50% hard limit
        uint256 projectedTotal = totalDynamicRewardsPaid + newReward;

        // Hard limit check
        if (projectedTotal > maxAllowedRewards) {
            return (false, 0);
        }

        // Soft landing mechanism: if global rewards >= 45%, reduce rewards
        // Calculate current percentage (in basis points, 10000 = 100%)
        uint256 currentPercentage;
        if (totalStaked > 0) {
            currentPercentage = (totalDynamicRewardsPaid * 10000) / totalStaked;
        }

        if (currentPercentage >= SOFT_LANDING_THRESHOLD * 100) {
            // Calculate reduction: for each 1% above 45%, reduce by 2%
            uint256 excessPercentage = currentPercentage - (SOFT_LANDING_THRESHOLD * 100);
            uint256 reductionPercentage = (excessPercentage * SOFT_LANDING_REDUCTION_RATE) / 100;

            // Apply reduction (max 100% reduction)
            if (reductionPercentage >= 10000) {
                return (false, 0);
            }

            uint256 reductionMultiplier = 10000 - reductionPercentage;
            adjustedReward = (newReward * reductionMultiplier) / 10000;

            // Re-check with adjusted reward
            if (totalDynamicRewardsPaid + adjustedReward > maxAllowedRewards) {
                adjustedReward = maxAllowedRewards > totalDynamicRewardsPaid 
                    ? maxAllowedRewards - totalDynamicRewardsPaid 
                    : 0;
            }

            return (adjustedReward > 0, adjustedReward);
        }

        return (true, newReward);
    }

    /**
     * @dev Check single reward cap (single reward ≤ staked × 50%)
     * @param user User address
     * @param reward Single reward amount
     * @return allowed Whether the reward is allowed
     */
    function checkSingleCap(address user, uint256 reward) internal view returns (bool allowed) {
        UserInfo storage userInfo = users[user];
        if (userInfo.totalStaked == 0) {
            return false;
        }

        uint256 maxSingleReward = (userInfo.totalStaked * SINGLE_CAP_MULTIPLIER) / 100;
        return reward <= maxSingleReward;
    }

    /**
     * @dev Check daily cap (daily rewards ≤ staked × 15%)
     * @param user User address
     * @param reward New reward amount to add
     * @return allowed Whether the reward is allowed
     */
    function checkDailyCap(address user, uint256 reward) internal returns (bool allowed) {
        UserInfo storage userInfo = users[user];
        if (userInfo.totalStaked == 0) {
            return false;
        }

        uint256 today = block.timestamp / 1 days;
        uint256 maxDailyReward = (userInfo.totalStaked * DAILY_CAP_MULTIPLIER) / 100;
        uint256 currentDailyReward = dailyRewards[user][today];
        uint256 projectedDailyReward = currentDailyReward + reward;

        if (projectedDailyReward > maxDailyReward) {
            // Update daily reward to max (for tracking)
            dailyRewards[user][today] = maxDailyReward;
            return false;
        }

        // Update daily reward tracking
        dailyRewards[user][today] = projectedDailyReward;
        return true;
    }

    /**
     * @dev Update user rewards (backend only)
     * @param user User address
     * @param rwAmount RWA token amount (18 decimals)
     * @param usdtAmount USDT amount (18 decimals)
     * @param stakeId Stake ID to prevent duplicate processing
     * 
     * CRITICAL SECURITY: This function follows Checks-Effects-Interactions pattern
     * Order: 1) All checks, 2) Lock and state updates, 3) External calls
     */
    function updateUserRewards(
        address user,
        uint256 rwAmount,
        uint256 usdtAmount,
        uint256 stakeId
    ) external nonReentrant whenNotPaused {
        require(msg.sender == backendAddress, "Only backend can call");

        // ========== Phase 1: All Checks ==========

        // 1.1 Prevent duplicate processing
        require(!processedStakes[stakeId], "Stake already processed");

        // 1.2 Single call limit check (prevent backend hack)
        require(usdtAmount <= maxRewardPerCall, "Exceeds max reward per call");

        // Check if this is RWA staking reward (usdtAmount == 0) or USDT staking reward
        if (usdtAmount == 0) {
            // RWA staking reward update
            RWAStakeInfo storage rwaStake = rwaStakes[user];
            require(rwAmount <= maxRewardPerCall, "Exceeds max reward per call");

            // Check contract RWA balance
            require(
                rwaToken.balanceOf(address(this)) >= rwAmount,
                "Insufficient RWA contract balance"
            );

            // Prevent duplicate processing
            processedStakes[stakeId] = true;

            // Update RWA stake rewards
            unchecked {
                rwaStake.rwaPending += rwAmount;
            }

            emit RewardsUpdated(user, rwAmount, 0, stakeId, block.timestamp);
            return;
        }

        // USDT staking reward update (existing logic)
        // 1.3 Real-time balance check
        // Convert usdtAmount from 18 decimals to 6 decimals for comparison
        uint256 usdtAmountIn6Decimals = usdtAmount / PRECISION_MULTIPLIER;
        uint256 contractBalance = usdtToken.balanceOf(address(this));
        require(contractBalance >= usdtAmountIn6Decimals, "Insufficient contract balance");

        // Cache user info to reduce storage reads (used in multiple checks)
        UserInfo storage userInfo = users[user];

        // 1.4 Multiple cap checks with soft landing
        (bool globalAllowed, uint256 adjustedUsdtAmount) = checkGlobalCap(usdtAmount);
        if (!globalAllowed) {
            emit CapCheckFailed(user, "Global", totalStaked / 2, usdtAmount, block.timestamp);
            revert("Dynamic rewards exceed global cap");
        }

        // Apply soft landing adjustment if needed
        if (adjustedUsdtAmount < usdtAmount) {
            // Adjust rwAmount proportionally
            rwAmount = (rwAmount * adjustedUsdtAmount) / usdtAmount;
            usdtAmount = adjustedUsdtAmount;
        }

        // 1.5 Single reward cap check
        if (!checkSingleCap(user, usdtAmount)) {
            uint256 maxSingleReward = (userInfo.totalStaked * SINGLE_CAP_MULTIPLIER) / 100;
            emit CapCheckFailed(user, "Single", maxSingleReward, usdtAmount, block.timestamp);
            revert("Exceeds single reward cap (50% of staked)");
        }

        // 1.6 Daily cap check (this also updates daily tracking)
        if (!checkDailyCap(user, usdtAmount)) {
            uint256 maxDailyReward = (userInfo.totalStaked * DAILY_CAP_MULTIPLIER) / 100;
            emit CapCheckFailed(user, "Daily", maxDailyReward, dailyRewards[user][block.timestamp / 1 days], block.timestamp);
            revert("Exceeds daily cap (15% of staked)");
        }

        // ========== Phase 2: State Updates (Effects) ==========

        // 2.1 Immediately set lock flag (prevent reentrancy)
        processedStakes[stakeId] = true;

        // 2.2 Update user balances (using cached storage pointer)
        unchecked {
            userInfo.rwaPending += rwAmount;
            userInfo.usdtRewards += usdtAmount;
        }

        // 2.3 Update global statistics (unchecked for gas optimization)
        unchecked {
            totalDynamicRewardsPaid += usdtAmount;
        }

        // ========== Phase 3: External Calls (Interactions) ==========

        // 3.1 Emit event
        emit RewardsUpdated(user, rwAmount, usdtAmount, stakeId, block.timestamp);
    }

    /**
     * @dev Update user node level (backend only)
     * @param user User address
     * @param level New node level (1-9)
     */
    function updateNodeLevel(address user, uint8 level) external nonReentrant whenNotPaused {
        require(msg.sender == backendAddress, "Only backend can call");
        require(level >= 1 && level <= 9, "Invalid node level");

        uint8 oldLevel = users[user].nodeLevel;
        require(level != oldLevel, "Level unchanged");

        users[user].nodeLevel = level;
        // Keep RWA stake node level in sync (for RWA-only stakers)
        if (rwaStakes[user].totalStakedRWA > 0) {
            rwaStakes[user].nodeLevel = level;
        }

        emit NodeLevelUpdated(user, oldLevel, level, block.timestamp);
    }

    /**
     * @dev Emergency exit is only available for locked USDT principal positions.
     * Refundable principal is proportional to completed full days, then the standard 8% immediate-exit fee applies.
     */
    function emergencyWithdraw(uint256 lockIndex) external nonReentrant whenNotPaused {
        USDTLockedPrincipal storage lockedPrincipal = usdtLockedPrincipals[msg.sender][lockIndex];

        require(!lockedPrincipal.isWithdrawn, "Principal already withdrawn");
        require(block.timestamp < lockedPrincipal.lockEndTime, "Lock already completed");

        uint256 elapsedDays = (block.timestamp - lockedPrincipal.lockStartTime) / 1 days;
        require(elapsedDays > 0, "No completed lock day");

        uint256 grossRefund = (lockedPrincipal.principalAmount * elapsedDays) / lockedPrincipal.lockPeriod;
        require(grossRefund > 0, "No amount to refund");
        require(grossRefund >= MIN_WITHDRAWAL_AMOUNT, "Below minimum withdrawal amount");

        uint256 burnAmount = grossRefund / 2;
        _burnStRWA(msg.sender, burnAmount);

        lockedPrincipal.isWithdrawn = true;
        _decreaseUserStakeTotals(msg.sender, lockedPrincipal.totalAmount, 0);

        uint256 netAmount = _payoutUsdtImmediate(msg.sender, grossRefund);
        emit EmergencyWithdrawal(msg.sender, netAmount, lockedPrincipal.principalAmount - grossRefund);
    }

    /**
     * @dev Pause contract
     */
    function pause() external onlyOwner {
        _pause();
    }

    /**
     * @dev Unpause contract
     */
    function unpause() external onlyOwner {
        _unpause();
    }

    /**
     * @dev Get RWA stake info for tax calculation
     * @param user User address
     * @return totalStaked_ Total staked RWA amount
     * @return weightedAverageTime Weighted average holding time
     */
    function getRWAStakeInfoForTax(address user) external view returns (uint256 totalStaked_, uint256 weightedAverageTime) {
        RWAStakeInfo storage rwaStakeInfo = rwaStakes[user];
        totalStaked_ = rwaStakeInfo.totalStakedRWA;

        // Calculate weighted average holding time (same logic as USDT stake)
        uint256 totalWeightedTime = 0;
        uint256 totalAmount = 0;

        for (uint256 i = 0; i < stakeHistory[user].length; i++) {
            uint256 timeDiff = block.timestamp - stakeHistory[user][i].timestamp;
            totalWeightedTime += stakeHistory[user][i].amount * timeDiff;
            totalAmount += stakeHistory[user][i].amount;
        }

        if (totalAmount > 0) {
            weightedAverageTime = totalWeightedTime / totalAmount;
        }

        return (totalStaked_, weightedAverageTime);
    }

    function getEmergencyWithdrawPreview(address user, uint256 lockIndex) external view returns (
        uint256 grossRefund,
        uint256 netRefund,
        uint256 elapsedDays,
        uint256 totalLockDays,
        bool eligible
    ) {
        USDTLockedPrincipal storage lockedPrincipal = usdtLockedPrincipals[user][lockIndex];
        totalLockDays = lockedPrincipal.lockPeriod;

        if (lockedPrincipal.isWithdrawn || block.timestamp >= lockedPrincipal.lockEndTime || totalLockDays == 0) {
            return (0, 0, 0, totalLockDays, false);
        }

        elapsedDays = (block.timestamp - lockedPrincipal.lockStartTime) / 1 days;
        if (elapsedDays == 0) {
            return (0, 0, 0, totalLockDays, false);
        }

        grossRefund = (lockedPrincipal.principalAmount * elapsedDays) / totalLockDays;
        (, , , netRefund) = _splitImmediateFee(grossRefund);
        eligible = grossRefund >= MIN_WITHDRAWAL_AMOUNT;
    }

    function getUSDTLockedPrincipals(address user) external view returns (
        uint256[] memory stakeIds,
        uint256[] memory amounts,
        uint256[] memory lockStartTimes,
        uint256[] memory lockEndTimes,
        bool[] memory canWithdraw,
        bool[] memory isWithdrawn
    ) {
        USDTLockedPrincipal[] storage locks = usdtLockedPrincipals[user];
        uint256 length = locks.length;

        stakeIds = new uint256[](length);
        amounts = new uint256[](length);
        lockStartTimes = new uint256[](length);
        lockEndTimes = new uint256[](length);
        canWithdraw = new bool[](length);
        isWithdrawn = new bool[](length);

        for (uint256 i = 0; i < length; i++) {
            stakeIds[i] = locks[i].stakeId;
            amounts[i] = locks[i].principalAmount;
            lockStartTimes[i] = locks[i].lockStartTime;
            lockEndTimes[i] = locks[i].lockEndTime;
            canWithdraw[i] = !locks[i].isWithdrawn && block.timestamp >= locks[i].lockEndTime;
            isWithdrawn[i] = locks[i].isWithdrawn;
        }
    }

    /**
     * @dev Get locked RWA principals for a user
     * @param user User address
     * @return stakeIds Array of stake IDs
     * @return amounts Array of principal amounts
     * @return lockStartTimes Array of lock start times
     * @return lockEndTimes Array of lock end times
     * @return canWithdraw Array of whether can withdraw
     * @return isWithdrawn Array of whether withdrawn
     */
    function getRWALockedPrincipals(address user) external view returns (
        uint256[] memory stakeIds,
        uint256[] memory amounts,
        uint256[] memory lockStartTimes,
        uint256[] memory lockEndTimes,
        bool[] memory canWithdraw,
        bool[] memory isWithdrawn
    ) {
        RWALockedPrincipal[] storage locks = rwaLockedPrincipals[user];
        uint256 length = locks.length;

        stakeIds = new uint256[](length);
        amounts = new uint256[](length);
        lockStartTimes = new uint256[](length);
        lockEndTimes = new uint256[](length);
        canWithdraw = new bool[](length);
        isWithdrawn = new bool[](length);

        for (uint256 i = 0; i < length; i++) {
            stakeIds[i] = locks[i].stakeId;
            amounts[i] = locks[i].principalAmount;
            lockStartTimes[i] = locks[i].lockStartTime;
            lockEndTimes[i] = locks[i].lockEndTime;
            canWithdraw[i] = !locks[i].isWithdrawn && block.timestamp >= locks[i].lockEndTime;
            isWithdrawn[i] = locks[i].isWithdrawn;
        }
    }
}

contracts/StRWA.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title StRWA
 * @dev Staked RWA - 实体资产代币化凭证
 * 
 * stRWA 代表用户持有的实体资产凭证
 * 1 stRWA = 1 USDT 等值的实体资产
 * 可在二级市场交易或等待实体资产清结算
 * 
 * 核心功能：
 * - 仅 StakingContract 可以铸造/销毁
 * - Owner 可以设置 StakingContract 地址
 * - 支持批量转账（用于实体资产清结算）
 */
contract StRWA is ERC20, Ownable {
    // 质押合约地址（只有质押合约可以铸造/销毁）
    address public stakingContract;

    struct BalanceLock {
        uint256 amount;
        uint256 unlockTime;
    }

    mapping(address => BalanceLock[]) private accountLocks;
    mapping(address => uint256) private nextLockIndex;
    mapping(address => uint256) public lockedBalance;

    // 事件
    event StakingContractUpdated(address indexed oldContract, address indexed newContract);
    event Minted(address indexed to, uint256 amount);
    event LockedMinted(address indexed to, uint256 amount, uint256 unlockTime);
    event Burned(address indexed from, uint256 amount);
    event LocksReleased(address indexed account, uint256 amount);

    /**
     * @dev 构造函数
     */
    constructor() ERC20("Staked RWA", "stRWA") Ownable(msg.sender) {
        // 初始供应量为 0，通过 mint 函数铸造
    }

    /**
     * @dev 设置质押合约地址（仅Owner可调用）
     * @param _stakingContract 质押合约地址
     */
    function setStakingContract(address _stakingContract) external onlyOwner {
        require(_stakingContract != address(0), "StRWA: Invalid address");
        require(_stakingContract != stakingContract, "StRWA: Same address");

        address oldContract = stakingContract;
        stakingContract = _stakingContract;

        emit StakingContractUpdated(oldContract, _stakingContract);
    }

    /**
     * @dev 铸造 stRWA（仅质押合约可调用）
     * 
     * 使用场景：
     * - 用户质押时：50%转换为 stRWA
     * - 用户选择"持RWA模式"提现时：120%收益转换为 stRWA
     * 
     * @param to 接收地址
     * @param amount 铸造数量（18 decimals）
     */
    function mint(address to, uint256 amount) external {
        require(msg.sender == stakingContract, "StRWA: Only staking contract");
        require(to != address(0), "StRWA: Invalid address");
        require(amount > 0, "StRWA: Amount must be greater than zero");

        _mintWithOptionalLock(to, amount, 0);
    }

    function mintLocked(address to, uint256 amount, uint256 lockDuration) external {
        require(msg.sender == stakingContract, "StRWA: Only staking contract");
        require(to != address(0), "StRWA: Invalid address");
        require(amount > 0, "StRWA: Amount must be greater than zero");
        require(lockDuration > 0, "StRWA: Invalid lock duration");

        _mintWithOptionalLock(to, amount, lockDuration);
    }

    /**
     * @dev 销毁 stRWA（仅质押合约可调用）
     * 
     * 使用场景：
     * - 用户解锁 stRWA 时
     * - 用户互换 stRWA → RWA 时
     * 
     * @param from 销毁地址
     * @param amount 销毁数量（18 decimals）
     */
    function burn(address from, uint256 amount) external {
        require(msg.sender == stakingContract, "StRWA: Only staking contract");
        require(from != address(0), "StRWA: Invalid address");
        require(amount > 0, "StRWA: Amount must be greater than zero");
        require(balanceOf(from) >= amount, "StRWA: Insufficient balance");

        _releaseExpiredLocks(from);
        _burn(from, amount);
        emit Burned(from, amount);
    }

    /**
     * @dev 批量转账（用于实体资产清结算）
     * 
     * 使用场景：
     * - 项目方定期回购 stRWA
     * - 实体资产清结算时批量转账
     * 
     * @param recipients 接收地址数组
     * @param amounts 转账数量数组（18 decimals）
     */
    function batchTransfer(
        address[] calldata recipients,
        uint256[] calldata amounts
    ) external onlyOwner {
        require(recipients.length == amounts.length, "StRWA: Arrays length mismatch");
        require(recipients.length > 0, "StRWA: Empty arrays");

        for (uint256 i = 0; i < recipients.length; i++) {
            require(recipients[i] != address(0), "StRWA: Invalid recipient");
            require(amounts[i] > 0, "StRWA: Invalid amount");
            _transfer(msg.sender, recipients[i], amounts[i]);
        }
    }

    /**
     * @dev 检查是否可以铸造/销毁
     * @return 如果 stakingContract 已设置返回 true
     */
    function isReady() external view returns (bool) {
        return stakingContract != address(0);
    }

    function releaseExpiredLocks(address account) external returns (uint256 releasedAmount) {
        return _releaseExpiredLocks(account);
    }

    function availableBalanceOf(address account) external view returns (uint256) {
        return balanceOf(account) - getLockedBalance(account);
    }

    function getLockedBalance(address account) public view returns (uint256 currentLocked) {
        currentLocked = lockedBalance[account];
        uint256 cursor = nextLockIndex[account];
        BalanceLock[] storage locks = accountLocks[account];

        while (cursor < locks.length && locks[cursor].unlockTime <= block.timestamp) {
            currentLocked -= locks[cursor].amount;
            cursor++;
        }
    }

    function getLocks(address account) external view returns (
        uint256[] memory amounts,
        uint256[] memory unlockTimes,
        bool[] memory released
    ) {
        BalanceLock[] storage locks = accountLocks[account];
        uint256 length = locks.length;

        amounts = new uint256[](length);
        unlockTimes = new uint256[](length);
        released = new bool[](length);

        for (uint256 i = 0; i < length; i++) {
            amounts[i] = locks[i].amount;
            unlockTimes[i] = locks[i].unlockTime;
            released[i] = i < nextLockIndex[account] || locks[i].unlockTime <= block.timestamp;
        }
    }

    function _mintWithOptionalLock(address to, uint256 amount, uint256 lockDuration) internal {
        _mint(to, amount);
        emit Minted(to, amount);

        if (lockDuration > 0) {
            uint256 unlockTime = block.timestamp + lockDuration;
            accountLocks[to].push(BalanceLock({ amount: amount, unlockTime: unlockTime }));
            lockedBalance[to] += amount;
            emit LockedMinted(to, amount, unlockTime);
        }
    }

    function _releaseExpiredLocks(address account) internal returns (uint256 releasedAmount) {
        uint256 cursor = nextLockIndex[account];
        BalanceLock[] storage locks = accountLocks[account];

        while (cursor < locks.length && locks[cursor].unlockTime <= block.timestamp) {
            releasedAmount += locks[cursor].amount;
            cursor++;
        }

        if (releasedAmount > 0) {
            lockedBalance[account] -= releasedAmount;
            nextLockIndex[account] = cursor;
            emit LocksReleased(account, releasedAmount);
        }
    }

    function _update(address from, address to, uint256 value) internal override {
        if (from != address(0) && msg.sender != stakingContract) {
            _releaseExpiredLocks(from);
            require(balanceOf(from) - lockedBalance[from] >= value, "StRWA: Amount exceeds unlocked balance");
        }

        super._update(from, to, value);

        if (from != address(0) && lockedBalance[from] > balanceOf(from)) {
            lockedBalance[from] = balanceOf(from);
        }
    }
}

contracts/SwapContract.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title SwapContract
 * @dev 双币互换合约 - stRWA ↔ RWA
 * 
 * 提供内部流动性，不依赖 DEX
 * 简化版：固定 1:1 比例（后续可升级为 AMM 曲线）
 * 
 * 核心功能：
 * - stRWA → RWA 互换（无税）
 * - RWA → stRWA 互换（无税，鼓励持有）
 * - 池子管理（初始化、补充流动性）
 */
contract SwapContract is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;
    
    // 代币地址
    IERC20 public immutable rwaToken;
    IERC20 public immutable stRwaToken;
    
    // 互换池余额
    uint256 public rwaPoolBalance;
    uint256 public stRwaPoolBalance;
    
    // AMM 常量乘积 k = x * y
    uint256 public constantProduct;
    
    // 互换限额配置
    uint256 public maxDailySwapPerUser = 1000000 * 10**18; // 100万代币/天/用户
    uint256 public maxDailySwapGlobal = 10000000 * 10**18; // 1000万代币/天/全局
    
    // 每日互换记录（user => day => amount）
    mapping(address => mapping(uint256 => uint256)) public dailySwapAmount;
    mapping(uint256 => uint256) public globalDailySwapAmount; // day => amount
    
    // 互换开关（紧急情况下可以暂停）
    bool public swapEnabled = true;
    
    // 事件
    event SwapStRWAToRWA(
        address indexed user,
        uint256 stRwaAmount,
        uint256 rwaAmount
    );
    
    event SwapRWAToStRWA(
        address indexed user,
        uint256 rwaAmount,
        uint256 stRwaAmount
    );
    
    event PoolUpdated(
        uint256 rwaBalance,
        uint256 stRwaBalance
    );
    
    event SwapEnabledUpdated(bool enabled);
    event SwapLimitExceeded(address indexed user, string limitType, uint256 limit, uint256 requested);
    event ConstantProductUpdated(uint256 oldK, uint256 newK);
    
    /**
     * @dev 构造函数
     * @param _rwaToken RWA 代币地址
     * @param _stRwaToken stRWA 代币地址
     */
    constructor(address _rwaToken, address _stRwaToken) Ownable(msg.sender) {
        require(_rwaToken != address(0), "SwapContract: Invalid RWA token address");
        require(_stRwaToken != address(0), "SwapContract: Invalid stRWA token address");
        
        rwaToken = IERC20(_rwaToken);
        stRwaToken = IERC20(_stRwaToken);
    }
    
    /**
     * @dev 初始化互换池（项目方提供初始流动性）
     * 
     * 使用场景：
     * - 合约部署后，项目方提供初始流动性
     * - 建议：至少 10,000 USDT 等值的代币
     * 
     * @param rwaAmount RWA 代币数量（18 decimals）
     * @param stRwaAmount stRWA 代币数量（18 decimals）
     */
    function initializePool(uint256 rwaAmount, uint256 stRwaAmount) external onlyOwner {
        require(rwaPoolBalance == 0 && stRwaPoolBalance == 0, "SwapContract: Pool already initialized");
        require(rwaAmount > 0 && stRwaAmount > 0, "SwapContract: Invalid amounts");
        
        rwaToken.safeTransferFrom(msg.sender, address(this), rwaAmount);
        stRwaToken.safeTransferFrom(msg.sender, address(this), stRwaAmount);
        
        rwaPoolBalance = rwaAmount;
        stRwaPoolBalance = stRwaAmount;
        
        // 初始化常量乘积 k = x * y
        constantProduct = rwaAmount * stRwaAmount;
        
        emit PoolUpdated(rwaPoolBalance, stRwaPoolBalance);
        emit ConstantProductUpdated(0, constantProduct);
    }
    
    /**
     * @dev 计算 AMM 输出金额（基于 x * y = k）
     * @param inputAmount 输入金额
     * @param inputReserve 输入池子余额
     * @param outputReserve 输出池子余额
     * @return outputAmount 输出金额
     */
    function calculateAMMOutput(
        uint256 inputAmount,
        uint256 inputReserve,
        uint256 outputReserve
    ) internal pure returns (uint256 outputAmount) {
        require(inputReserve > 0 && outputReserve > 0, "SwapContract: Insufficient liquidity");
        
        // AMM 公式：x * y = k
        // 当输入 inputAmount 时：
        // (inputReserve + inputAmount) * (outputReserve - outputAmount) = k
        // 解出：outputAmount = (inputAmount * outputReserve) / (inputReserve + inputAmount)
        
        uint256 numerator = inputAmount * outputReserve;
        uint256 denominator = inputReserve + inputAmount;
        
        // 防止除零和精度损失
        require(denominator > 0, "SwapContract: Division by zero");
        
        return numerator / denominator;
    }
    
    /**
     * @dev 检查互换限额
     * @param user 用户地址
     * @param amount 互换金额
     * @return allowed 是否允许
     */
    function checkSwapLimit(address user, uint256 amount) internal returns (bool allowed) {
        uint256 today = block.timestamp / 1 days;
        
        // 检查用户每日限额
        uint256 userDailyAmount = dailySwapAmount[user][today];
        if (userDailyAmount + amount > maxDailySwapPerUser) {
            emit SwapLimitExceeded(user, "UserDaily", maxDailySwapPerUser, userDailyAmount + amount);
            return false;
        }
        
        // 检查全局每日限额
        uint256 globalDailyAmount = globalDailySwapAmount[today];
        if (globalDailyAmount + amount > maxDailySwapGlobal) {
            emit SwapLimitExceeded(user, "GlobalDaily", maxDailySwapGlobal, globalDailyAmount + amount);
            return false;
        }
        
        // 更新记录
        dailySwapAmount[user][today] = userDailyAmount + amount;
        globalDailySwapAmount[today] = globalDailyAmount + amount;
        
        return true;
    }
    
    /**
     * @dev stRWA → RWA（使用 AMM 曲线）
     * 
     * AMM 公式：x * y = k
     * 当用户输入 stRwaAmount 时，计算能获得多少 RWA
     * 
     * @param stRwaAmount stRWA 数量（18 decimals）
     */
    function swapStRWAToRWA(uint256 stRwaAmount) external nonReentrant {
        require(swapEnabled, "SwapContract: Swap is disabled");
        require(stRwaAmount > 0, "SwapContract: Amount must be greater than zero");
        require(constantProduct > 0, "SwapContract: Pool not initialized");
        
        // 检查互换限额
        require(checkSwapLimit(msg.sender, stRwaAmount), "SwapContract: Swap limit exceeded");
        
        // 计算 AMM 输出金额
        uint256 rwaAmount = calculateAMMOutput(stRwaAmount, stRwaPoolBalance, rwaPoolBalance);
        require(rwaAmount > 0, "SwapContract: Output amount too small");
        require(rwaPoolBalance >= rwaAmount, "SwapContract: Insufficient RWA pool");
        
        // 从用户转账 stRWA 到合约
        stRwaToken.safeTransferFrom(msg.sender, address(this), stRwaAmount);
        
        // 从合约转账 RWA 给用户
        rwaToken.safeTransfer(msg.sender, rwaAmount);
        
        // 更新池子余额
        stRwaPoolBalance += stRwaAmount;
        rwaPoolBalance -= rwaAmount;
        
        // 更新常量乘积（理论上应该保持不变，但由于整数除法可能有微小误差）
        // 为了保持 k 的准确性，重新计算：k = x * y
        uint256 oldK = constantProduct;
        constantProduct = rwaPoolBalance * stRwaPoolBalance;
        
        emit SwapStRWAToRWA(msg.sender, stRwaAmount, rwaAmount);
        emit PoolUpdated(rwaPoolBalance, stRwaPoolBalance);
        emit ConstantProductUpdated(oldK, constantProduct);
    }
    
    /**
     * @dev RWA → stRWA（使用 AMM 曲线，鼓励持有）
     * 
     * AMM 公式：x * y = k
     * 当用户输入 rwaAmount 时，计算能获得多少 stRWA
     * 
     * @param rwaAmount RWA 数量（18 decimals）
     */
    function swapRWAToStRWA(uint256 rwaAmount) external nonReentrant {
        require(swapEnabled, "SwapContract: Swap is disabled");
        require(rwaAmount > 0, "SwapContract: Amount must be greater than zero");
        require(constantProduct > 0, "SwapContract: Pool not initialized");
        
        // 检查互换限额
        require(checkSwapLimit(msg.sender, rwaAmount), "SwapContract: Swap limit exceeded");
        
        // 计算 AMM 输出金额
        uint256 stRwaAmount = calculateAMMOutput(rwaAmount, rwaPoolBalance, stRwaPoolBalance);
        require(stRwaAmount > 0, "SwapContract: Output amount too small");
        require(stRwaPoolBalance >= stRwaAmount, "SwapContract: Insufficient stRWA pool");
        
        // 从用户转账 RWA 到合约
        rwaToken.safeTransferFrom(msg.sender, address(this), rwaAmount);
        
        // 从合约转账 stRWA 给用户
        stRwaToken.safeTransfer(msg.sender, stRwaAmount);
        
        // 更新池子余额
        rwaPoolBalance += rwaAmount;
        stRwaPoolBalance -= stRwaAmount;
        
        // 更新常量乘积（理论上应该保持不变，但由于整数除法可能有微小误差）
        // 为了保持 k 的准确性，重新计算：k = x * y
        uint256 oldK = constantProduct;
        constantProduct = rwaPoolBalance * stRwaPoolBalance;
        
        emit SwapRWAToStRWA(msg.sender, rwaAmount, stRwaAmount);
        emit PoolUpdated(rwaPoolBalance, stRwaPoolBalance);
        emit ConstantProductUpdated(oldK, constantProduct);
    }
    
    /**
     * @dev 项目方补充流动性
     * 
     * 使用场景：
     * - 池子余额不足时补充
     * - 维持池子健康度
     * 
     * @param rwaAmount RWA 代币数量（18 decimals，0 表示不补充）
     * @param stRwaAmount stRWA 代币数量（18 decimals，0 表示不补充）
     */
    function addLiquidity(uint256 rwaAmount, uint256 stRwaAmount) external onlyOwner {
        if (rwaAmount > 0) {
            rwaToken.safeTransferFrom(msg.sender, address(this), rwaAmount);
            rwaPoolBalance += rwaAmount;
        }
        
        if (stRwaAmount > 0) {
            stRwaToken.safeTransferFrom(msg.sender, address(this), stRwaAmount);
            stRwaPoolBalance += stRwaAmount;
        }
        
        // 更新常量乘积
        if (constantProduct == 0) {
            // 如果还未初始化，初始化 k
            constantProduct = rwaPoolBalance * stRwaPoolBalance;
        } else {
            // 如果已初始化，重新计算 k（补充流动性会增加 k）
            uint256 oldK = constantProduct;
            constantProduct = rwaPoolBalance * stRwaPoolBalance;
            emit ConstantProductUpdated(oldK, constantProduct);
        }
        
        emit PoolUpdated(rwaPoolBalance, stRwaPoolBalance);
    }
    
    /**
     * @dev 设置用户每日互换限额
     * @param newLimit 新的限额（18 decimals）
     */
    function setMaxDailySwapPerUser(uint256 newLimit) external onlyOwner {
        require(newLimit > 0, "SwapContract: Invalid limit");
        maxDailySwapPerUser = newLimit;
    }
    
    /**
     * @dev 设置全局每日互换限额
     * @param newLimit 新的限额（18 decimals）
     */
    function setMaxDailySwapGlobal(uint256 newLimit) external onlyOwner {
        require(newLimit > 0, "SwapContract: Invalid limit");
        maxDailySwapGlobal = newLimit;
    }
    
    /**
     * @dev 设置互换开关（紧急情况下可以暂停）
     * @param _enabled 是否启用
     */
    function setSwapEnabled(bool _enabled) external onlyOwner {
        require(swapEnabled != _enabled, "SwapContract: Same status");
        swapEnabled = _enabled;
        emit SwapEnabledUpdated(_enabled);
    }
    
    /**
     * @dev 查询池子状态
     * @return rwaBalance RWA 池子余额
     * @return stRwaBalance stRWA 池子余额
     * @return constantProduct_ 常量乘积 k
     * @return swapRate 当前互换比例（基于 AMM 曲线计算）
     */
    function getPoolStatus() external view returns (
        uint256 rwaBalance,
        uint256 stRwaBalance,
        uint256 constantProduct_,
        uint256 swapRate
    ) {
        // 计算当前互换比例（1 stRWA = ? RWA）
        // 使用 AMM 公式计算小额互换的比例
        if (rwaPoolBalance > 0 && stRwaPoolBalance > 0) {
            // 计算 1 stRWA 能换多少 RWA（使用 1e18 作为单位）
            uint256 oneStRWA = 1 * 10**18;
            uint256 rwaOutput = calculateAMMOutput(oneStRWA, stRwaPoolBalance, rwaPoolBalance);
            // swapRate = (rwaOutput / 1e18) * 100，表示百分比
            swapRate = (rwaOutput * 100) / (1 * 10**18);
        } else {
            swapRate = 100; // 默认 1:1
        }
        
        return (rwaPoolBalance, stRwaPoolBalance, constantProduct, swapRate);
    }
    
    /**
     * @dev 查询当前互换比例（基于 AMM 曲线）
     * @param amount 互换金额（用于计算实际比例）
     * @param isStRWAToRWA true = stRWA → RWA, false = RWA → stRWA
     * @return outputAmount 输出金额
     * @return swapRate 互换比例（百分比，100 = 1:1）
     */
    function getSwapRate(uint256 amount, bool isStRWAToRWA) external view returns (
        uint256 outputAmount,
        uint256 swapRate
    ) {
        if (constantProduct == 0 || amount == 0) {
            return (0, 100); // 默认 1:1
        }
        
        if (isStRWAToRWA) {
            outputAmount = calculateAMMOutput(amount, stRwaPoolBalance, rwaPoolBalance);
        } else {
            outputAmount = calculateAMMOutput(amount, rwaPoolBalance, stRwaPoolBalance);
        }
        
        // 计算比例：outputAmount / amount * 100
        swapRate = (outputAmount * 100) / amount;
        
        return (outputAmount, swapRate);
    }
    
    /**
     * @dev 获取用户今日互换金额
     * @param user 用户地址
     * @return amount 今日互换金额
     */
    function getUserDailySwapAmount(address user) external view returns (uint256 amount) {
        uint256 today = block.timestamp / 1 days;
        return dailySwapAmount[user][today];
    }
    
    /**
     * @dev 获取全局今日互换金额
     * @return amount 今日互换金额
     */
    function getGlobalDailySwapAmount() external view returns (uint256 amount) {
        uint256 today = block.timestamp / 1 days;
        return globalDailySwapAmount[today];
    }
}

contracts/TeamDividendPool.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/**
 * @title TeamDividendPool
 * @dev 团队业绩分红池 - 1-of-2 签名方案（后端 + 管理员）
 * 用户质押产生的分红记录需后端与管理员双签后批量写入，用户可随时提取
 */
contract TeamDividendPool is ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;

    IERC20 public immutable usdt;

    /// @dev 1-of-2：后端地址与管理员地址，batchRecordDividend 需两者各自签名
    address public backendSigner;
    address public adminSigner;

    /// @dev 用户分红余额（USDT 6位精度）
    mapping(address => uint256) public dividendBalances;

    /// @dev 已结算未提取总额
    uint256 public settledUnwithdrawn;
    /// @dev 预留 gas/运营费用
    uint256 public reservedGas;

    /// @dev 单笔提取上限 100,000 USDT
    uint256 public constant MAX_WITHDRAWAL_PER_TX = 100_000 * 10**6;
    /// @dev 每日提取次数上限
    uint256 public constant MAX_WITHDRAWALS_PER_DAY = 10;
    /// @dev autoTransfer 24小时冷却
    uint256 public constant AUTO_TRANSFER_COOLDOWN = 24 hours;
    mapping(address => uint256) public dailyWithdrawalCount;
    mapping(address => uint256) public lastWithdrawalDay;

    /// @dev 防重放
    mapping(bytes32 => bool) public usedNonces;

    /// @dev autoTransfer 24小时冷却
    uint256 public lastAutoTransferTime;

    event DividendsRecorded(uint256 indexed month, uint256 userCount, uint256 totalAmount);
    event DividendWithdrawn(address indexed user, uint256 amount);
    event AutoTransferExecuted(address indexed targetPool, uint256 amount);
    event SignersUpdated(address backendSigner, address adminSigner);
    event ReservedGasUpdated(uint256 oldValue, uint256 newValue);
    event FundsReceived(address indexed from, uint256 amount, string source);

    constructor(
        address _usdt,
        address _backendSigner,
        address _adminSigner,
        uint256 _reservedGas
    ) {
        require(_usdt != address(0), "Invalid USDT");
        require(_backendSigner != address(0), "Invalid backend");
        require(_adminSigner != address(0), "Invalid admin");
        require(_backendSigner != _adminSigner, "Signers must differ");

        usdt = IERC20(_usdt);
        backendSigner = _backendSigner;
        adminSigner = _adminSigner;
        reservedGas = _reservedGas;
    }

    /// @notice 接收质押划拨（由质押合约调用，划拨规则：质押金额 × 50% × 18% = 9%）
    function receiveStakeFunds(uint256 amount) external {
        require(usdt.transferFrom(msg.sender, address(this), amount), "Transfer failed");
        emit FundsReceived(msg.sender, amount, "stake");
    }

    /// @notice 接收手续费划拨
    function receiveFeeFunds(uint256 amount) external {
        require(usdt.transferFrom(msg.sender, address(this), amount), "Transfer failed");
        emit FundsReceived(msg.sender, amount, "fee");
    }

    /// @notice 更新签名者（仅管理员可调，兼容旧版）
    function setSigners(address _backendSigner, address _adminSigner) external {
        require(msg.sender == adminSigner, "Unauthorized");
        require(_backendSigner != address(0) && _adminSigner != address(0), "Invalid");
        require(_backendSigner != _adminSigner, "Signers must differ");
        backendSigner = _backendSigner;
        adminSigner = _adminSigner;
        emit SignersUpdated(_backendSigner, _adminSigner);
    }

    /// @notice 更新预留 gas
    function updateReservedGas(uint256 newValue) external {
        require(msg.sender == adminSigner, "Unauthorized");
        emit ReservedGasUpdated(reservedGas, newValue);
        reservedGas = newValue;
    }

    /// @notice 更新后端签名地址（仅 adminSigner）
    function updateBackendSigner(address newSigner) external {
        require(msg.sender == adminSigner, "Unauthorized");
        require(newSigner != address(0), "Invalid address");
        require(newSigner != adminSigner, "Signers must differ");
        backendSigner = newSigner;
    }

    /// @notice 更新管理员签名地址（仅当前 adminSigner）
    function updateAdminSigner(address newSigner) external {
        require(msg.sender == adminSigner, "Unauthorized");
        require(newSigner != address(0), "Invalid address");
        require(newSigner != backendSigner, "Signers must differ");
        adminSigner = newSigner;
    }

    /// @notice 批量记录用户分红（需 backend 与 admin 双签）
    function batchRecordDividend(
        address[] calldata users,
        uint256[] calldata amounts,
        uint256 month,
        bytes32 nonce,
        bytes calldata backendSig,
        bytes calldata adminSig
    ) external whenNotPaused {
        require(users.length == amounts.length, "Length mismatch");
        require(!usedNonces[nonce], "Nonce already used");

        bytes32 msgHash = keccak256(abi.encodePacked(users, amounts, month, nonce));
        bytes32 ethHash = keccak256(
            abi.encodePacked("\x19Ethereum Signed Message:\n32", msgHash)
        );

        require(_recoverSigner(ethHash, backendSig) == backendSigner, "Invalid backend sig");
        require(_recoverSigner(ethHash, adminSig) == adminSigner, "Invalid admin sig");

        usedNonces[nonce] = true;
        uint256 total = 0;
        for (uint256 i = 0; i < users.length; i++) {
            require(amounts[i] > 0, "Zero amount");
            dividendBalances[users[i]] += amounts[i];
            total += amounts[i];
        }
        settledUnwithdrawn += total;

        emit DividendsRecorded(month, users.length, total);
    }

    /// @notice 用户提取分红
    function withdrawDividend(uint256 amount) external nonReentrant whenNotPaused {
        require(amount > 0 && amount <= MAX_WITHDRAWAL_PER_TX, "Invalid amount");
        require(dividendBalances[msg.sender] >= amount, "Insufficient balance");

        uint256 today = block.timestamp / 1 days;
        if (lastWithdrawalDay[msg.sender] < today) {
            dailyWithdrawalCount[msg.sender] = 0;
            lastWithdrawalDay[msg.sender] = today;
        }
        require(dailyWithdrawalCount[msg.sender] < MAX_WITHDRAWALS_PER_DAY, "Daily limit");

        dividendBalances[msg.sender] -= amount;
        settledUnwithdrawn -= amount;
        dailyWithdrawalCount[msg.sender]++;

        // 扣除 8% 手续费
        uint256 fee = (amount * 8) / 100;
        uint256 netAmount = amount - fee;
        
        usdt.safeTransfer(msg.sender, netAmount);
        if (fee > 0) {
            usdt.safeTransfer(adminSigner, fee);
        }

        emit DividendWithdrawn(msg.sender, netAmount);
    }

    /// @notice 自动调拨（单次不超过可用余额 50%，24h 冷却）
    function autoTransfer(address targetPool, uint256 amount) external whenNotPaused {
        require(msg.sender == backendSigner, "Unauthorized");
        require(
            block.timestamp >= lastAutoTransferTime + AUTO_TRANSFER_COOLDOWN,
            "Cooldown active"
        );
        uint256 maxTransfer = getAvailableBalance() / 2;
        require(amount > 0 && amount <= maxTransfer, "Exceeds 50% limit");

        lastAutoTransferTime = block.timestamp;
        usdt.safeTransfer(targetPool, amount);

        emit AutoTransferExecuted(targetPool, amount);
    }

    /// @notice 可用余额 = 总余额 - 已结算未提取 - 预留
    function getAvailableBalance() public view returns (uint256) {
        uint256 total = usdt.balanceOf(address(this));
        if (total <= settledUnwithdrawn + reservedGas) return 0;
        return total - settledUnwithdrawn - reservedGas;
    }

    /// @notice 查询分红池完整状态（供后端轮询）
    function getPoolStatus() external view returns (
        uint256 totalBalance,
        uint256 _settledUnwithdrawn,
        uint256 _reservedGas,
        uint256 availableBalance
    ) {
        totalBalance = usdt.balanceOf(address(this));
        _settledUnwithdrawn = settledUnwithdrawn;
        _reservedGas = reservedGas;
        availableBalance = getAvailableBalance();
    }

    function pause() external {
        require(msg.sender == adminSigner, "Unauthorized");
        _pause();
    }

    function unpause() external {
        require(msg.sender == adminSigner, "Unauthorized");
        _unpause();
    }

    function _recoverSigner(bytes32 ethHash, bytes memory sig) internal pure returns (address) {
        require(sig.length == 65, "Invalid sig length");
        bytes32 r;
        bytes32 s;
        uint8 v;
        assembly {
            r := mload(add(sig, 32))
            s := mload(add(sig, 64))
            v := byte(0, mload(add(sig, 96)))
        }
        if (v < 27) v += 27;
        return ecrecover(ethHash, v, r, s);
    }
}

contracts/TestUSDT.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";

/**
 * @title TestUSDT
 * @dev 测试用的 USDT 代币，用于本地开发和测试
 * 
 * 特性:
 * - 6 位小数（与真实 USDT 相同）
 * - 任何人都可以铸造（仅用于测试）
 * - 初始供应量 100 万 USDT
 */
contract TestUSDT is ERC20 {
    /**
     * @dev 构造函数
     * 铸造 100 万 USDT 给部署者
     */
    constructor() ERC20("Test USDT", "USDT") {
        // 铸造 100 万 USDT (6 decimals)
        _mint(msg.sender, 1000000 * 10**6);
    }
    
    /**
     * @dev 返回代币精度（6 位小数）
     */
    function decimals() public pure override returns (uint8) {
        return 6;
    }
    
    /**
     * @dev 铸造代币（仅用于测试）
     * @param to 接收地址
     * @param amount 铸造数量（6 位小数）
     */
    function mint(address to, uint256 amount) external {
        _mint(to, amount);
    }
    
    /**
     * @dev 批量铸造（方便测试）
     * @param recipients 接收地址数组
     * @param amounts 铸造数量数组
     */
    function mintBatch(address[] calldata recipients, uint256[] calldata amounts) external {
        require(recipients.length == amounts.length, "Arrays length mismatch");
        for (uint256 i = 0; i < recipients.length; i++) {
            _mint(recipients[i], amounts[i]);
        }
    }
}

contracts/TreasuryContract.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title TreasuryContract
 * @dev Treasury 管理合约 - 投资份额、回报分配、月度分红
 * 
 * Features:
 * - 投资份额记录（用户质押的50%进入Treasury）
 * - 投资回报分配（40%用户分红，30%再投资，20%流动性，10%风险准备金）
 * - 月度分红机制
 * - 投资记录管理
 * - 提取限制（每日限额）
 * - 多签控制（可选）
 */
contract TreasuryContract is Ownable, Pausable, ReentrancyGuard {
    using SafeERC20 for IERC20;
    
    // Token address
    IERC20 public immutable usdtToken;
    
    // StakingContract address (only StakingContract can deposit)
    address public stakingContractAddress;
    
    // 资金分类
    uint256 public totalDeposited;        // 总存入金额
    uint256 public totalInvested;         // 已投资金额
    uint256 public totalReturns;          // 投资回报总额
    uint256 public totalDistributed;      // 已分配金额
    
    // 用户投资份额记录
    mapping(address => uint256) public userInvestmentShares;
    uint256 public totalInvestmentShares;
    
    // 投资回报分配比例
    uint256 public constant USER_DIVIDEND_SHARE = 40;  // 40% 用户分红
    uint256 public constant REINVEST_SHARE = 30;       // 30% 再投资
    uint256 public constant LIQUIDITY_SHARE = 20;      // 20% 流动性
    uint256 public constant RESERVE_SHARE = 10;       // 10% 风险准备金
    
    // 投资记录
    struct Investment {
        address projectAddress;
        uint256 amount;
        uint256 timestamp;
        uint256 expectedReturn;
        uint256 actualReturn;
        bool isActive;
    }
    
    mapping(uint256 => Investment) public investments;
    uint256 public investmentCounter;
    
    // 提取限制
    uint256 public maxWithdrawalPerDay = 100000 * 10**6;  // 每日最大提取100,000 USDT
    mapping(uint256 => uint256) public dailyWithdrawn;   // 每日已提取金额
    
    // 月度分红记录
    struct MonthlyDividend {
        uint256 month;              // 月份标识（timestamp / 30 days）
        uint256 totalDividend;      // 总分红金额
        uint256 distributedAmount;  // 已分配金额
        bool isDistributed;         // 是否已分配
    }
    
    mapping(uint256 => MonthlyDividend) public monthlyDividends;
    mapping(address => mapping(uint256 => bool)) public userDividendClaimed; // user => month => claimed
    
    // 多签控制（可选）
    address public multiSigWallet;
    bool public multiSigEnabled = false;
    
    // 地址配置
    address public liquidityPoolAddress;  // 流动性池地址
    address public reserveFundAddress;    // 风险准备金地址
    
    // 事件
    event DepositReceived(address indexed from, address indexed user, uint256 amount, uint256 timestamp);
    event InvestmentMade(uint256 indexed investmentId, address projectAddress, uint256 amount, uint256 expectedReturn, uint256 timestamp);
    event ReturnReceived(uint256 indexed investmentId, uint256 amount, uint256 timestamp);
    event DividendDistributed(uint256 indexed month, uint256 totalDividend, uint256 userShare, uint256 reinvest, uint256 liquidity, uint256 reserve, uint256 timestamp);
    event UserDividendClaimed(address indexed user, uint256 indexed month, uint256 amount, uint256 timestamp);
    event WithdrawalMade(address indexed to, uint256 amount, string reason, uint256 timestamp);
    event StakingContractUpdated(address indexed oldAddress, address indexed newAddress);
    event MultiSigWalletUpdated(address indexed oldAddress, address indexed newAddress, bool enabled);
    event LiquidityPoolAddressUpdated(address indexed oldAddress, address indexed newAddress);
    event ReserveFundAddressUpdated(address indexed oldAddress, address indexed newAddress);
    event MaxWithdrawalPerDayUpdated(uint256 oldLimit, uint256 newLimit);
    
    /**
     * @dev Constructor
     * @param _usdtToken USDT token address
     */
    constructor(address _usdtToken) Ownable(msg.sender) {
        require(_usdtToken != address(0), "TreasuryContract: Invalid USDT token address");
        usdtToken = IERC20(_usdtToken);
    }
    
    /**
     * @dev Modifier: Only StakingContract can call
     */
    modifier onlyStakingContract() {
        require(msg.sender == stakingContractAddress, "TreasuryContract: Only staking contract can call");
        _;
    }
    
    /**
     * @dev Modifier: Only Owner or MultiSig can call
     */
    modifier onlyOwnerOrMultiSig() {
        if (multiSigEnabled) {
            require(msg.sender == multiSigWallet, "TreasuryContract: Only multi-sig wallet can call");
        } else {
            require(msg.sender == owner(), "TreasuryContract: Only owner can call");
        }
        _;
    }
    
    /**
     * @dev 接收质押资金（仅 StakingContract 可调用）
     * @param amount 存入金额（6 decimals）
     * @param user 用户地址
     */
    function deposit(uint256 amount, address user) external onlyStakingContract whenNotPaused {
        require(amount > 0, "TreasuryContract: Amount must be greater than zero");
        require(user != address(0), "TreasuryContract: Invalid user address");
        
        // 从 StakingContract 转账 USDT
        usdtToken.safeTransferFrom(msg.sender, address(this), amount);
        
        // 记录用户投资份额
        userInvestmentShares[user] += amount;
        totalInvestmentShares += amount;
        totalDeposited += amount;
        
        emit DepositReceived(msg.sender, user, amount, block.timestamp);
    }
    
    /**
     * @dev 投资实体项目（仅Owner或多签）
     * @param projectAddress 项目地址
     * @param amount 投资金额（6 decimals）
     * @param expectedReturn 预期回报（6 decimals）
     */
    function invest(
        address projectAddress,
        uint256 amount,
        uint256 expectedReturn
    ) external onlyOwnerOrMultiSig whenNotPaused nonReentrant {
        require(amount > 0, "TreasuryContract: Amount must be greater than zero");
        require(projectAddress != address(0), "TreasuryContract: Invalid project address");
        
        uint256 availableBalance = usdtToken.balanceOf(address(this));
        require(availableBalance >= amount, "TreasuryContract: Insufficient balance");
        
        // 投资到实体项目
        usdtToken.safeTransfer(projectAddress, amount);
        
        // 记录投资
        uint256 investmentId = investmentCounter++;
        investments[investmentId] = Investment({
            projectAddress: projectAddress,
            amount: amount,
            timestamp: block.timestamp,
            expectedReturn: expectedReturn,
            actualReturn: 0,
            isActive: true
        });
        
        totalInvested += amount;
        
        emit InvestmentMade(investmentId, projectAddress, amount, expectedReturn, block.timestamp);
    }
    
    /**
     * @dev 接收投资回报（仅Owner或多签）
     * @param investmentId 投资ID
     * @param returnAmount 回报金额（6 decimals）
     */
    function receiveReturn(
        uint256 investmentId,
        uint256 returnAmount
    ) external onlyOwnerOrMultiSig whenNotPaused nonReentrant {
        require(returnAmount > 0, "TreasuryContract: Return amount must be greater than zero");
        
        Investment storage investment = investments[investmentId];
        require(investment.isActive, "TreasuryContract: Investment not active");
        
        // 从调用者转账回报到合约
        usdtToken.safeTransferFrom(msg.sender, address(this), returnAmount);
        
        investment.actualReturn += returnAmount;
        totalReturns += returnAmount;
        
        // 分配回报
        distributeReturns(returnAmount);
        
        emit ReturnReceived(investmentId, returnAmount, block.timestamp);
    }
    
    /**
     * @dev 分配投资回报
     * @param totalReturn 总回报金额（6 decimals）
     */
    function distributeReturns(uint256 totalReturn) internal {
        uint256 userDividend = (totalReturn * USER_DIVIDEND_SHARE) / 100;
        uint256 reinvest = (totalReturn * REINVEST_SHARE) / 100;
        uint256 liquidity = (totalReturn * LIQUIDITY_SHARE) / 100;
        uint256 reserve = totalReturn - userDividend - reinvest - liquidity; // 确保总和为100%
        
        // 记录月度分红（用户分红部分）
        uint256 currentMonth = block.timestamp / (30 days);
        MonthlyDividend storage monthlyDividend = monthlyDividends[currentMonth];
        
        if (!monthlyDividend.isDistributed) {
            monthlyDividend.month = currentMonth;
            monthlyDividend.totalDividend = userDividend;
            monthlyDividend.distributedAmount = 0;
            monthlyDividend.isDistributed = false;
        } else {
            monthlyDividend.totalDividend += userDividend;
        }
        
        // 再投资（保留在合约中，用于后续投资）
        // reinvest 保留在合约中，不需要转账
        
        // 流动性（转账到流动性池）
        if (liquidity > 0 && liquidityPoolAddress != address(0)) {
            usdtToken.safeTransfer(liquidityPoolAddress, liquidity);
        }
        
        // 风险准备金（转账到风险准备金地址）
        if (reserve > 0 && reserveFundAddress != address(0)) {
            usdtToken.safeTransfer(reserveFundAddress, reserve);
        }
        
        totalDistributed += totalReturn;
        
        emit DividendDistributed(
            currentMonth,
            monthlyDividend.totalDividend,
            userDividend,
            reinvest,
            liquidity,
            reserve,
            block.timestamp
        );
    }
    
    /**
     * @dev 用户领取月度分红
     * @param month 月份标识（timestamp / 30 days）
     */
    function claimMonthlyDividend(uint256 month) external whenNotPaused nonReentrant {
        require(!userDividendClaimed[msg.sender][month], "TreasuryContract: Dividend already claimed");
        
        MonthlyDividend storage monthlyDividend = monthlyDividends[month];
        require(monthlyDividend.isDistributed, "TreasuryContract: Dividend not distributed yet");
        require(monthlyDividend.totalDividend > 0, "TreasuryContract: No dividend for this month");
        
        // 计算用户应得分红
        uint256 userShare = userInvestmentShares[msg.sender];
        if (userShare == 0 || totalInvestmentShares == 0) {
            revert("TreasuryContract: No investment share");
        }
        
        uint256 userDividend = (monthlyDividend.totalDividend * userShare) / totalInvestmentShares;
        require(userDividend > 0, "TreasuryContract: Dividend amount too small");
        
        // 标记为已领取
        userDividendClaimed[msg.sender][month] = true;
        monthlyDividend.distributedAmount += userDividend;
        
        // 转账分红
        usdtToken.safeTransfer(msg.sender, userDividend);
        
        emit UserDividendClaimed(msg.sender, month, userDividend, block.timestamp);
    }
    
    /**
     * @dev 提取资金（仅Owner或多签，有限制）
     * @param to 接收地址
     * @param amount 提取金额（6 decimals）
     * @param reason 提取原因
     */
    function withdraw(
        address to,
        uint256 amount,
        string memory reason
    ) external onlyOwnerOrMultiSig whenNotPaused nonReentrant {
        require(amount > 0, "TreasuryContract: Amount must be greater than zero");
        require(to != address(0), "TreasuryContract: Invalid address");
        
        // 检查每日限额
        uint256 currentDay = block.timestamp / 1 days;
        require(
            dailyWithdrawn[currentDay] + amount <= maxWithdrawalPerDay,
            "TreasuryContract: Daily withdrawal limit exceeded"
        );
        
        // 检查可用余额（不能提取已投资部分）
        uint256 availableBalance = usdtToken.balanceOf(address(this));
        uint256 maxWithdrawable = availableBalance > totalInvested ? availableBalance - totalInvested : 0;
        require(amount <= maxWithdrawable, "TreasuryContract: Cannot withdraw invested funds");
        
        // 更新每日提取记录
        dailyWithdrawn[currentDay] += amount;
        
        // 转账
        usdtToken.safeTransfer(to, amount);
        
        emit WithdrawalMade(to, amount, reason, block.timestamp);
    }
    
    /**
     * @dev 紧急提取（仅Owner，需要更高权限）
     * @param to 接收地址
     * @param amount 提取金额（6 decimals）
     */
    function emergencyWithdraw(
        address to,
        uint256 amount
    ) external onlyOwner nonReentrant {
        require(to != address(0), "TreasuryContract: Invalid address");
        require(amount > 0, "TreasuryContract: Amount must be greater than zero");
        
        // 紧急情况下可以提取所有资金
        usdtToken.safeTransfer(to, amount);
        
        emit WithdrawalMade(to, amount, "Emergency withdrawal", block.timestamp);
    }
    
    /**
     * @dev 设置 StakingContract 地址
     * @param _stakingContractAddress StakingContract 地址
     */
    function setStakingContractAddress(address _stakingContractAddress) external onlyOwner {
        require(_stakingContractAddress != address(0), "TreasuryContract: Invalid address");
        address oldAddress = stakingContractAddress;
        stakingContractAddress = _stakingContractAddress;
        emit StakingContractUpdated(oldAddress, _stakingContractAddress);
    }
    
    /**
     * @dev 设置多签钱包
     * @param _multiSigWallet 多签钱包地址
     * @param _enabled 是否启用多签
     */
    function setMultiSigWallet(address _multiSigWallet, bool _enabled) external onlyOwner {
        address oldAddress = multiSigWallet;
        multiSigWallet = _multiSigWallet;
        multiSigEnabled = _enabled;
        emit MultiSigWalletUpdated(oldAddress, _multiSigWallet, _enabled);
    }
    
    /**
     * @dev 设置流动性池地址
     * @param _liquidityPoolAddress 流动性池地址
     */
    function setLiquidityPoolAddress(address _liquidityPoolAddress) external onlyOwner {
        address oldAddress = liquidityPoolAddress;
        liquidityPoolAddress = _liquidityPoolAddress;
        emit LiquidityPoolAddressUpdated(oldAddress, _liquidityPoolAddress);
    }
    
    /**
     * @dev 设置风险准备金地址
     * @param _reserveFundAddress 风险准备金地址
     */
    function setReserveFundAddress(address _reserveFundAddress) external onlyOwner {
        address oldAddress = reserveFundAddress;
        reserveFundAddress = _reserveFundAddress;
        emit ReserveFundAddressUpdated(oldAddress, _reserveFundAddress);
    }
    
    /**
     * @dev 设置每日最大提取限额
     * @param newLimit 新的限额（6 decimals）
     */
    function setMaxWithdrawalPerDay(uint256 newLimit) external onlyOwner {
        require(newLimit > 0, "TreasuryContract: Invalid limit");
        uint256 oldLimit = maxWithdrawalPerDay;
        maxWithdrawalPerDay = newLimit;
        emit MaxWithdrawalPerDayUpdated(oldLimit, newLimit);
    }
    
    /**
     * @dev 查询用户投资份额
     * @param user 用户地址
     * @return share 投资份额
     */
    function getUserInvestmentShare(address user) external view returns (uint256 share) {
        return userInvestmentShares[user];
    }
    
    /**
     * @dev 查询用户应得分红（基于总分红金额）
     * @param user 用户地址
     * @param totalDividend 总分红金额
     * @return dividend 用户应得分红
     */
    function getUserDividend(address user, uint256 totalDividend) external view returns (uint256 dividend) {
        if (totalInvestmentShares == 0) {
            return 0;
        }
        return (totalDividend * userInvestmentShares[user]) / totalInvestmentShares;
    }
    
    /**
     * @dev 查询用户月度分红
     * @param user 用户地址
     * @param month 月份标识
     * @return dividend 用户应得分红
     * @return claimed 是否已领取
     */
    function getUserMonthlyDividend(address user, uint256 month) external view returns (uint256 dividend, bool claimed) {
        MonthlyDividend storage monthlyDividend = monthlyDividends[month];
        if (!monthlyDividend.isDistributed || monthlyDividend.totalDividend == 0) {
            return (0, false);
        }
        
        if (totalInvestmentShares == 0) {
            return (0, false);
        }
        
        uint256 userShare = userInvestmentShares[user];
        dividend = (monthlyDividend.totalDividend * userShare) / totalInvestmentShares;
        claimed = userDividendClaimed[user][month];
        
        return (dividend, claimed);
    }
    
    /**
     * @dev 查询投资信息
     * @param investmentId 投资ID
     * @return investment 投资信息
     */
    function getInvestment(uint256 investmentId) external view returns (Investment memory investment) {
        return investments[investmentId];
    }
    
    /**
     * @dev 查询合约状态
     * @return totalDeposited_ 总存入金额
     * @return totalInvested_ 已投资金额
     * @return totalReturns_ 投资回报总额
     * @return totalDistributed_ 已分配金额
     * @return totalInvestmentShares_ 总投资份额
     * @return availableBalance 可用余额
     */
    function getTreasuryStatus() external view returns (
        uint256 totalDeposited_,
        uint256 totalInvested_,
        uint256 totalReturns_,
        uint256 totalDistributed_,
        uint256 totalInvestmentShares_,
        uint256 availableBalance
    ) {
        totalDeposited_ = totalDeposited;
        totalInvested_ = totalInvested;
        totalReturns_ = totalReturns;
        totalDistributed_ = totalDistributed;
        totalInvestmentShares_ = totalInvestmentShares;
        availableBalance = usdtToken.balanceOf(address(this));
    }
    
    /**
     * @dev Pause contract
     */
    function pause() external onlyOwner {
        _pause();
    }
    
    /**
     * @dev Unpause contract
     */
    function unpause() external onlyOwner {
        _unpause();
    }
}

